import heapq
import sys
from collections import defaultdict
from typing import List, Tuple

class SSP:
    def __init__(self, n: int, source: int, sink: int):
        self.n = n
        self.source = source
        self.sink = sink
        self.adj = [[] for _ in range(n)]
        self.edges = []  # list of (u, flow, cap, cost, origcost)

    def add_edge(self, a: int, b: int, cap: int, cost: int) -> int:
        result = len(self.edges)
        self.adj[a].append(len(self.edges))
        self.edges.append([b, 0, cap, cost, cost])
        self.adj[b].append(len(self.edges))
        self.edges.append([a, 0, 0, -cost, -cost])
        return result

    def djk(self) -> Tuple[int, int]:
        INF = 10**18
        states = [{'dist': INF, 'prev': -1, 'maxf': 0} for _ in range(self.n)]
        states[self.source] = {'dist': 0, 'prev': -2, 'maxf': 10**18}
        pq = [(states[self.source]['dist'], self.source)]

        while pq:
            d, v = heapq.heappop(pq)
            if d != states[v]['dist']:
                continue
            for edid in self.adj[v]:
                u, flow, cap, cost, _ = self.edges[edid]
                if flow < cap and states[u]['dist'] > states[v]['dist'] + cost:
                    states[u]['dist'] = states[v]['dist'] + cost
                    states[u]['prev'] = edid
                    states[u]['maxf'] = min(states[v]['maxf'], cap - flow)
                    heapq.heappush(pq, (states[u]['dist'], u))

        lastid = states[self.sink]['prev']
        extraflow = states[self.sink]['maxf']
        atcost = 0

        if lastid == -1:
            return (0, 0)

        id_ = lastid
        while id_ != -2:
            e = self.edges[id_]
            self.edges[id_][1] += extraflow
            self.edges[id_ ^ 1][1] -= extraflow
            atcost += e[4]  # origcost
            id_ = states[self.edges[id_ ^ 1][0]]['prev']

        for id_ in range(len(self.edges)):
            v = self.edges[id_ ^ 1][0]
            u = self.edges[id_][0]
            if states[v]['prev'] != -1 and states[u]['prev'] != -1:
                self.edges[id_][3] += states[v]['dist'] - states[u]['dist']

        return (extraflow, atcost)

    def mfmc(self) -> Tuple[int, int]:
        flow = 0
        cost = 0

        if any(e[1] > 0 and e[3] < 0 for e in self.edges):
            self.bellamanford()

        while True:
            extraflow, atcost = self.djk()
            if extraflow <= 0:
                break
            flow += extraflow
            cost += extraflow * atcost

        return (flow, cost)

    def bellamanford(self):
        INF = 10**18
        dist = [INF] * self.n
        dist[self.source] = 0

        for rep in range(self.n):
            changed = False
            for id_ in range(len(self.edges)):
                v = self.edges[id_ ^ 1][0]
                u = self.edges[id_][0]
                if self.edges[id_][1] < self.edges[id_][2] and dist[v] != INF and dist[u] > dist[v] + self.edges[id_][3]:
                    dist[u] = dist[v] + self.edges[id_][3]
                    changed = True
            if not changed:
                break

        for id_ in range(len(self.edges)):
            v = self.edges[id_ ^ 1][0]
            u = self.edges[id_][0]
            if dist[v] < INF and dist[u] < INF:
                self.edges[id_][3] += dist[v] - dist[u]

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    c = int(next(it))
    d = int(next(it))

    a = [int(next(it)) for _ in range(k)]

    e = [[] for _ in range(n + 1)]
    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        e[x].append(y)
        e[y].append(x)

    max_time = 120
    nd = 0
    to = [[0] * (n + 1) for _ in range(max_time)]
    for i in range(max_time):
        for j in range(1, n + 1):
            to[i][j] = nd
            nd += 1

    S = nd
    nd += 1
    T = nd
    nd += 1

    flow = SSP(nd, S, T)

    for i in range(k):
        flow.add_edge(S, to[0][a[i]], 1, 0)

    for i in range(max_time):
        flow.add_edge(to[i][1], T, k, c * i)

    for i in range(max_time - 1):
        for j in range(1, n + 1):
            for kk in e[j]:
                for z in range(53):  # 0 to 52 inclusive
                    flow.add_edge(to[i][j], to[i + 1][kk], 1, d * (2 * z + 1))
            flow.add_edge(to[i][j], to[i + 1][j], k, 0)

    p0, p1 = flow.mfmc()
