import sys
import heapq
from collections import defaultdict

class Edge:
    __slots__ = ('src', 'dst', 'cap', 'cost', 'rev')
    def __init__(self, src, dst, cap, cost, rev=None):
        self.src = src
        self.dst = dst
        self.cap = cap
        self.cost = cost
        self.rev = rev

class FlowBase:
    def __init__(self, n=0):
        self.adj = [[] for _ in range(n)]

    def size(self):
        return len(self.adj)

    def add_edge(self, src, dst, cap, cost):
        if cap <= 0:
            return
        forward = Edge(src, dst, cap, cost, None)
        backward = Edge(dst, src, 0, -cost, None)
        forward.rev = backward
        backward.rev = forward
        self.adj[src].append(forward)
        self.adj[dst].append(backward)

class MinCostFlow(FlowBase):
    def __init__(self, n=0):
        super().__init__(n)
        self.min_cost = 0
        self.total_cost = 0
        self.supp = [0] * n
        self.ptnl = [0] * n

    def add_edge(self, src, dst, cap, cost):
        if src == dst:
            return
        if cap <= 0:
            return
        if cost < 0:
            self.supp[src] -= cap
            self.supp[dst] += cap
            self.min_cost += cap * cost
            self.total_cost -= cap * cost
            super().add_edge(dst, src, cap, -cost)
        else:
            self.total_cost += cap * cost
            super().add_edge(src, dst, cap, cost)

    def supply(self, node, vol):
        self.supp[node] += vol

    def _dijkstra(self, last):
        n = self.size()
        infty = self.total_cost + 1
        dist = [infty] * n
        # priority queue (max-heap using negative)
        pq = []
        for node in range(n):
            if self.supp[node] > 0:
                dist[node] = 0
                heapq.heappush(pq, (0, node))
        while pq:
            nsp, node = heapq.heappop(pq)
            if -nsp != dist[node]:
                continue
            self.ptnl[node] -= nsp
            if self.ptnl[node] > infty:
                self.ptnl[node] = infty
            dist[node] = None  # mark as invalid
            for e in self.adj[node]:
                if dist[e.dst] is None or e.cap == 0:
                    continue
                nd = self.ptnl[node] + e.cost - self.ptnl[e.dst]
                if dist[e.dst] is infty or nd < dist[e.dst]:
                    dist[e.dst] = nd
                    last[e.dst] = e
                    heapq.heappush(pq, (-nd, e.dst))

    def flow(self):
        n = self.size()
        while True:
            last = [None] * n
            self._dijkstra(last)
            shut = [False] * n
            aug = False
            for dst in range(n):
                if self.supp[dst] < 0 and last[dst] is not None:
                    resid = -self.supp[dst]
                    src = dst
                    block = None
                    while last[src] is not None and not shut[src]:
                        if resid >= last[src].cap:
                            resid = last[src].cap
                            block = src
                        src = last[src].src
                    if shut[src]:
                        block = src
                    else:
                        if resid >= self.supp[src]:
                            resid = self.supp[src]
                            block = src
                        # augment along path
                        node = dst
                        while node != src:
                            e = last[node]
                            e.cap -= resid
                            e.rev.cap += resid
                            node = e.src
                        self.supp[src] -= resid
                        self.supp[dst] += resid
                        self.min_cost += self.ptnl[dst] * resid
                        aug = True
                    if block is not None:
                        node = dst
                        while node != block:
                            shut[node] = True
                            node = last[node].src
                        shut[block] = True
            if not aug:
                break
        for s in self.supp:
            if s > 0:
                return False
        return True

    def optimal(self):
        if not self.flow():
            raise ValueError("No feasible flow")
        return self.min_cost

