		for (int e, i = t; i != s; i = ep[e])
			e = par[i], df = min(df, cap[e] - flo[e]);
		for (int e, i = t; i != s; i = ep[e])
			e = par[i], flo[e] += df, flo[e^1] -= df, price += df*cost[e];
		for (int i = 0; i < n; ++i) pot[i] = min(INF, dist[i] + pot[i]);
		return df; }
}

