		for(int j=0;j<C;j++) {
			int cost = (j+1)*(j+1) - j*j;
			for(int t=1;t<T;t++) {
				Flow::add_edge(a+(t-1)*n, b+t*n, 1, cost*d + c);
				Flow::add_edge(b+(t-1)*n, a+t*n, 1, cost*d + c);
			}
		}
	}

	Flow::mcf_pot_init(Flow::N);
	ll price = 0;
	ll flow = 0;
	while (ll df = Flow::mcf_update(source, sink, price, Flow::N)) flow += df;
	assert(flow==k);
	cout << price << nl;

	return 0;
}

