		int now=Q.front();Q.pop();flag[now]=0;
		for (int i=fi[now];i;i=ne[i])
			if (sl[i]&&dis[zz[i]]>dis[now]+w[i]){
				dis[zz[i]]=dis[now]+w[i];
				if (!flag[zz[i]]){
					flag[zz[i]]=1;
					Q.push(zz[i]);
				}
			}
	}
	return dis[T]<=1e9;
}
