from collections import deque
INF = 10**18

class Flow:
    def __init__(self, N):
        self.N = N
        self.adj = [[] for _ in range(N)]
        self.mc = 0

    def add_edge(self, a, b, c=1, p=0):
        if c > self.mc:
            self.mc = c
        self.adj[a].append([b, len(self.adj[b]), 0, c, p])
        self.adj[b].append([a, len(self.adj[a]) - 1, 0, 0, -p])

    def pot_init(self, n):
        self.pot = [0] * n
        for _ in range(1, n):
            updated = False
            for u in range(n):
                for e in self.adj[u]:
                    if e[3] > 0:  # capacity > 0
                        if self.pot[e[0]] > self.pot[u] + e[4]:
                            self.pot[e[0]] = self.pot[u] + e[4]
                            updated = True
            if not updated:
                break

    def mcf(self, s, t, n, sparse):
        self.vis = [False] * n
        self.dist = [INF] * n
        self.dist[s] = 0
        self.par = [-1] * n
        if sparse:
            q = deque([s])
            while q:
                u = q.popleft()
                if self.vis[u]:
                    continue
                self.vis[u] = True
                for e in self.adj[u]:
                    if e[2] < e[3]:  # flow < capacity
                        nd = self.dist[u] + self.pot[u] - self.pot[e[0]] + e[4]
                        if self.dist[e[0]] > nd:
                            self.dist[e[0]] = nd
                            self.par[e[0]] = e[1]
                            q.append(e[0])
        else:
            for _ in range(n):
                u = -1
                best = INF
                for i in range(n):
                    if not self.vis[i] and self.dist[i] < best:
                        best = self.dist[i]
                        u = i
                if u == -1:
                    break
                self.vis[u] = True
                for e in self.adj[u]:
                    if e[2] < e[3]:
                        nd = self.dist[u] + self.pot[u] - self.pot[e[0]] + e[4]
                        if self.dist[e[0]] > nd:
                            self.dist[e[0]] = nd
                            self.par[e[0]] = e[1]
        if self.dist[t] >= INF:
