class BFSMap:
    def __init__(self, r: int, c: int):
        self.R = r
        self.C = c
        self.E = [[0] * (c + 2) for _ in range(r + 2)]

    def setRC(self, r: int, c: int, w: int):
        self.E[r][c] = w

    def getRC(self, r: int, c: int) -> int:
        return self.E[r][c]

    def bfsAll(self, Q: List[Tuple[int, int]] = None) -> int:
        visited = [[0] * (self.C + 2) for _ in range(self.R + 2)]
        ret = 0
        if Q is None:
            for r in range(1, self.R + 1):
                for c in range(1, self.C + 1):
                    if self.E[r][c] and not visited[r][c]:
                        ret += 1
                        self.bfs(r, c, visited)
        else:
            for r, c in Q:
                if not visited[r][c]:
                    ret += 1
                    self.bfs(r, c, visited)
        return ret

    def bfs(self, rr: int, cc: int, visited: List[List[int]]):
        q = deque()
        q.append((rr, cc))
        visited[rr][cc] = 1
        while q:
            r, c = q.popleft()
            for i in range(4):
                r2 = r + dr[i]
                c2 = c + dc[i]
                if self.E[r2][c2] and not visited[r2][c2]:
                    q.append((r2, c2))
                    visited[r2][c2] = visited[r][c] + 1

    def g(self):
        R, C = map(int, sys.stdin.readline().split())
        bm = BFSMap(R, C)
        Q = [[], []]
        for r in range(1, R + 1):
            row = list(map(int, sys.stdin.readline().split()))
            for c, a in enumerate(row, 1):
                bm.setRC(r, c, a)
                if a:
                    Q[0].append((r, c))
        idx = 0
        ans = 0
        while True:
            a = bm.bfsAll(Q[idx])
            if a > 1:
                break
            elif a == 0:
                ans = 0
                break
            ans += 1
            X = []
            Q[1 - idx] = []
            for r, c in Q[idx]:
                a = 0
                for j in range(4):
                    r2 = r + dr[j]
                    c2 = c + dc[j]
                    if bm.getRC(r2, c2) == 0:
                        a += 1
                X.append(a)
            for i, (r, c) in enumerate(Q[idx]):
                a = bm.getRC(r, c) - X[i]
                if a <= 0:
                    a = 0
                else:
                    Q[1 - idx].append((r, c))
                bm.setRC(r, c, a)
            idx = 1 - idx
        print(ans)

class Number:
    def getDigitNum(self, xx: int) -> int:
        x = 1
        ret = 0
        while x < xx:
            x *= 10
            ret += 1
        return ret

    def getDigitSum(self, xx: int) -> int:
        x = xx
        a = 0
        while x:
            a += x % 10
            x //= 10
        return a

    def getMSB(self, xx: int) -> int:
        i = 0
        while (1 << i) <= xx:
            i += 1
        return i - 1

    def convertBinaryToBase(self, x: int, base: int) -> int:
        if x == 0:
            return 0
        return base * self.convertBinaryToBase(x // 2, base) + (x % 2)

    def findFactor(self, k: int) -> int:
        d = 2
        while d * d <= k:
            if k % d == 0:
                return d
            d += 1
        return 0

class Palindrome:
    def isPalindrome(self, xx: int) -> int:
        v = []
        x = xx
        while x > 0:
            v.append(x % 10)
            x //= 10
        n = len(v)
        for i in range(n // 2):
            if v[i] != v[n - i - 1]:
                return 0
        return 1

class BigNumber:
    def add(self, s1: str, s2: str) -> str:
        i = len(s1) - 1
        j = len(s2) - 1
        v = []
        while i >= 0 and j >= 0:
            a = ord(s1[i]) - ord('0') + ord(s2[j]) - ord('0')
            v.append(a)
            i -= 1
            j -= 1
        while i >= 0:
            a = ord(s1[i]) - ord('0')
            v.append(a)
            i -= 1
        while j >= 0:
            a = ord(s2[j]) - ord('0')
            v.append(a)
            j -= 1
        carry = 0
        for i in range(len(v)):
            carry += v[i]
            if carry >= 10:
                v[i] = carry - 10
                carry = 1
            else:
                v[i] = carry
                carry = 0
        if carry:
            v.append(carry)
        s3 = ""
        for i in range(len(v) - 1, -1, -1):
            s3 += chr(v[i] + ord('0'))
