class PSum:
    @staticmethod
    def makeSum1D(a: List[int], n: int) -> List[int]:
        ret = [0] * len(a)
        ret[0] = a[0]
        for i in range(1, len(a)):
            ret[i] = ret[i - 1] + a[i]
        return ret

    @staticmethod
    def makeSum2D(a: List[List[int]], n: int, m: int) -> List[List[int]]:
        ret = [[0] * m for _ in range(n)]
        for i in range(n):
            ret[i][0] = a[i][0]
            for j in range(1, m):
                ret[i][j] = ret[i][j - 1] + a[i][j]
        return ret

    @staticmethod
    def getSum1D(psum: List[int], a: int, b: int) -> int:
        if a == 0:
            return psum[b]
        return psum[b] - psum[a - 1]

    @staticmethod
    def getSum2D(psum: List[List[int]], r1: int, c1: int, r2: int, c2: int) -> int:
        ret = psum[r2][c2]
        if r1 > 0:
            ret -= psum[r1 - 1][c2]
        if c1 > 0:
            ret -= psum[r2][c1 - 1]
        if r1 > 0 and c1 > 0:
            ret += psum[r1 - 1][c1 - 1]
        return ret

class DisjointSet:
    def __init__(self, n: int):
        self.N = n
        self.P = list(range(n + 1))
        self.R = [0] * (n + 1)
        self.A = [1] * (n + 1)

    def getA(self, x: int) -> int:
        return self.A[x]

    def find_set(self, x: int) -> int:
        if self.P[x] == x:
            return x
        self.P[x] = self.find_set(self.P[x])
        return self.P[x]

    def union_set(self, x: int, y: int) -> int:
        px = self.find_set(x)
        py = self.find_set(y)
        if px == py:
            return px
        if self.R[px] > self.R[py]:
            self.P[py] = px
            self.A[px] += self.A[py]
            return px
        else:
            self.P[px] = py
            self.A[py] += self.A[px]
            if self.R[px] == self.R[py]:
                self.R[py] += 1
            return py

