            if A[i] > v[-1]:
                v.append(A[i])
            else:
                lo, hi = 0, len(v) - 1
                while lo < hi:
                    mid = (lo + hi) // 2
                    if v[mid] >= A[i]:
                        hi = mid
                    else:
                        lo = mid + 1
                v[hi] = A[i]
        return len(v)

