                v.append(A[i])
                v1.append(i)
            else:
                idx = bisect.bisect_left(v, A[i])
                v[idx] = A[i]
                if idx != 0:
                    p[i] = v1[idx - 1]
                v1[idx] = i
        ret = []
        i = v1[-1]
        while i != -1:
            ret.append(A[i])
