class TreeFromExpression:
    def make(self, s: str) -> Tuple[List[Tuple[int, int]], int]:
        cur = 1
        E = [(0, 0)] * 10000
        stack = []
        for ch in s:
            if '1' <= ch <= '9':
                E[cur] = (ord(ch) - ord('0'), 0)
                stack.append(cur)
                cur += 1
            elif ch == ')':
                a = stack.pop()
                b = stack.pop()
                E[cur] = (a, b)
                stack.append(cur)
                cur += 1
        root = cur - 1
        return E, root

