import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n_orig = int(next(it))
    a = [0] * 6
    if n_orig > 0:
        a[0] = int(next(it))
    if n_orig > 1:
        a[1] = int(next(it))
    if n_orig > 2:
        a[2] = int(next(it))
    if n_orig > 3:
        a[3] = int(next(it))
    if n_orig == 5:
        a[4] = int(next(it))
        n = n_orig - 1
    else:
        n = n_orig - 1

    # bubble sort on first n elements
    for i in range(n):
        for j in range(n - i - 1):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]

    t = (a[0] + a[n]) // 2

    # find first index i where a[i] > t (or i = n if none)
    i = -1
    while True:
        i += 1
        if i >= n or a[i] > t:
            break

    # find first index j from right where a[j] < t (or j = 0 if none)
    j = n + 1
    while True:
        j -= 1
        if j <= 0 or a[j] < t:
            break

    # output based on the same conditional logic
    if a[i] - t < t - a[j] and a[i - 1] - t > a[i] - t:
        result = a[i]
    elif i - 1 >= 0 and a[i - 1] - t < t - a[j]:
        result = a[i - 1]
    else:
        result = a[j]

    print(result)

