import sys

def find_parent(parent, x):
    if parent[x] != x:
        parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    if rank[x] >= rank[y]:
        parent[y] = x
        rank[x] += 1
    else:
        parent[x] = y
        rank[y] += 1

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    P = int(data[0])
    K = int(data[1])

    MOD = 1000000007

