MOD = 10**9 + 7

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    p = int(data[0])
    k = int(data[1])

    par = list(range(p))

    def find(x: int) -> int:
        # path compression
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        par[rx] = ry

    for i in range(1, p):
        val = (k * i) % p
        if val != 0:
            union(val, i)

    seen = set()
    for i in range(1, p):
        seen.add(find(i))

    pw = len(seen)
    if k == 1:
        pw = p

    ans = pow(p, pw, MOD)
    print(ans)

if __name__ == "__main__":
    solve()

