def modular_exponentiation(x, n, M):
    if n == 0:
        return 1
    elif n % 2 == 0:
        return modular_exponentiation((x * x) % M, n // 2, M)
    else:
        return (x * modular_exponentiation((x * x) % M, (n - 1) // 2, M)) % M

def find_parent(root, parent):
    while parent[root] != root:
        root = parent[root]
    return root

