    par1 = find_parent(root1, parent)
    par2 = find_parent(root2, parent)
    if rating[par1] >= rating[par2]:
        parent[par2] = par1
        rating[par1] += 1
    else:
        parent[par1] = par2
        rating[par2] += 1

