import sys
import math

mod = 1000000007

def add(i, j):
    return (i + j) % mod

def mult(i, j):
    return (i * j) % mod

def pwr(i, k):
    r = 1
    while k:
        if k & 1:
            r = mult(r, i)
        i = mult(i, i)
        k >>= 1
    return r

def beb(a, m):
    global mod
    original_mod = mod
    mod = m
    s = int(math.isqrt(m))
    P = [-1] * (m + 1)
    r = 1
    d = pwr(a, m - 2)
    for i in range(s + 1):
        if P[r] == -1:
            P[r] = i
        r = mult(r, d)
        if r == 1:
            mod = original_mod
            return i + 1
    d = pwr(a, s)
    r = d
    for i in range(1, s + 1):
        if P[r] != -1:
            mod = original_mod
            return s * i + P[r]
        r = mult(r, d)
    mod = original_mod
    return -1

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    p = int(data[0])
    k = int(data[1])
    if k == 1:
        print(pwr(p, p))
    elif k == 0:
        print(pwr(p, p - 1))
    else:
        order = beb(k, p)
        print(pwr(p, (p - 1) // order))

