import sys
import random

MOD = 1000000007

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))

    def find_set(self, a):
        if a == self.parent[a]:
            return a
        base = self.find_set(self.parent[a])
        self.parent[a] = base
        return base

    def union_set(self, a, b):
        a = self.find_set(a)
        b = self.find_set(b)
        if a != b:
            if random.randint(0, 1):
                a, b = b, a
            self.parent[b] = a

