import sys
from collections import deque

INF = 10**9

def edmondsKarp(n, source, sink, flow, cap):
    # returns max flow
    while True:
        pre = [-1] * n
        d = [0] * n
        d[source] = INF
        q = deque()
        q.append(source)
        while q and pre[sink] < 0:
            t = q.popleft()
            for i in range(n):
                if pre[i] < 0 and (j := cap[t][i] - flow[t][i]) > 0:
                    pre[i] = t
                    d[i] = min(d[t], j)
                    q.append(i)
        if pre[sink] < 0:
            break
        i = sink
        while i != source:
            flow[pre[i]][i] += d[sink]
            flow[i][pre[i]] -= d[sink]
            i = pre[i]
    return sum(flow[source][i] for i in range(n))

def solve(A, B, vis, check, n, bi, bj, mat, b, t):
    q = deque()
    vis[A*n+B] = 0
    q.append((A, B))
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]
    while q:
        now = q.popleft()
        p = now[0]*n + now[1]
        dis = vis[p]
        if check and (mat[bi*n+bj][p] <= dis or t <= dis):
            if mat[bi*n+bj][p] < dis or t < dis:
                vis[p] = INF + 1
            continue
        for d in dirs:
            i = now[0] + d[0]
            j = now[1] + d[1]
            if i < 0 or j < 0 or i == n or j == n:
                continue
            if b[i][j] < '0' or b[i][j] > '9':
                continue
            qq = i*n + j
            if vis[qq] != INF:
                continue
            vis[qq] = dis + 1
            q.append((i, j))

