        self.adjusted = []
        self.back = None

class Edge:
    __slots__ = ('from_node', 'to_node', 'flow', 'opposite')
    def __init__(self):
        self.from_node = None
        self.to_node = None
        self.flow = 0
        self.opposite = None

def adjust(e, d):
    if e is None:
        return d
    d = adjust(e.from_node.back, min(d, e.flow))
    e.flow -= d
    e.opposite.flow += d
    return d

def connect(a, b, w):
    ea = Edge()
    eb = Edge()
    ea.from_node = a
    ea.to_node = b
    ea.flow = w
    ea.opposite = eb
    eb.from_node = b
    eb.to_node = a
    eb.flow = 0
    eb.opposite = ea
    a.adjusted.append(ea)
    b.adjusted.append(eb)

def max_flow(g, source, sink):
    result = 0
    while True:
        for u in g:
            u.age = 0
        q = deque()
        q.append(source)
        source.age = 1
        while q and sink.age == 0:
            u = q.popleft()
            for e in u.adjusted:
                v = e.to_node
                if v.age != 0 or e.flow == 0:
