import sys
from collections import deque

def is_valid(r, c, n):
    return 0 <= r < n and 0 <= c < n

def get_path(flo, counter):
    parent = [-1] * (counter + 1)
    parent[0] = 0
    stack = [0]
    while stack:
        top = stack.pop()
        if top == counter:
            break
        for i in range(counter + 1):
            if flo[top][i] and parent[i] == -1:
                parent[i] = top
                stack.append(i)
    if parent[counter] == -1:
        return 0
    ans = 10000
    pos = counter
    while pos != 0:
        ans = min(ans, flo[parent[pos]][pos])
        pos = parent[pos]
    pos = counter
    while pos != 0:
        flo[parent[pos]][pos] -= ans
        flo[pos][parent[pos]] += ans
        pos = parent[pos]
    return ans

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    t = int(next(it))
    # read first grid
    inp = [list(next(it).strip()) for _ in range(n)]
    # initialize arrays
    source_cap = [[0]*n for _ in range(n)]
    sink_cap = [[0]*n for _ in range(n)]
    source_num = [[-1]*n for _ in range(n)]
    sink_num = [[-1]*n for _ in range(n)]
    plant = [[[0]*(t+1) for _ in range(n)] for _ in range(n)]
    # process first grid
    for i in range(n):
        for j in range(n):
            ch = inp[i][j]
            if ch == 'Y' or ch == 'Z':
                plant[i][j][0] = ord(ch) - ord('X')  # Y->1, Z->2
                source_cap[i][j] = 0
            else:
                plant[i][j][0] = 0
                source_cap[i][j] = ord(ch) - ord('0')
    # read second grid
    inp = [list(next(it).strip()) for _ in range(n)]
    for i in range(n):
        for j in range(n):
            ch = inp[i][j]
            if ch == 'Y' or ch == 'Z':
                plant[i][j][0] = ord(ch) - ord('X')
                sink_cap[i][j] = 0
            else:
                plant[i][j][0] = 0
                sink_cap[i][j] = ord(ch) - ord('0')
    # propagate plant over time
    dr = [0, 0, -1, 1]
    dc = [-1, 1, 0, 0]
    for curr_time in range(1, t+1):
        for i in range(n):
            for j in range(n):
                plant[i][j][curr_time] = plant[i][j][curr_time-1]
        for i in range(n):
            for j in range(n):
