            if sink_cap[i][j] != 0:
                sink_num[i][j] = counter
                counter += 1
            else:
                sink_num[i][j] = -1
    # initialize flow matrix (size counter+1)
    flo = [[0]*(counter+1) for _ in range(counter+1)]
    # BFS from each source to find reachable sinks within time t
    for i in range(n):
        for j in range(n):
            if source_cap[i][j] == 0:
                continue
            source = source_num[i][j]
            vis = [[False]*n for _ in range(n)]
            q = deque()
            q.append((0, i, j))
