            ll tr = dfs(u, min(pushed, edges[viz].cap - edges[viz].flow));
            if(tr == 0) continue; 

            edges[viz].flow += tr;
            edges[viz ^ 1].flow -= tr; 
            return tr;
        }
        return 0;
    }

