        ll f = 0;
        while(true) {
            fill(all(level), -1);
            level[s] = 0;
            q.push(s);
            if(!bfs()) break; 
            fill(all(ptr), 0);
            while(ll pushed = dfs(s, flow_inf))
                f += pushed;
