from collections import deque
import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    lab = [list(next(it).strip()) for _ in range(n)]
    rea = [list(next(it).strip()) for _ in range(n)]

    obs = [[0]*n for _ in range(n)]
    tim = [[-1]*n for _ in range(n)]
    dii = [[-1]*n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            obs[i][j] = 1 if lab[i][j] == 'Y' else 0

    # BFS for Z positions (tim)
    dx = [-1, 0, 0, 1]
    dy = [0, -1, 1, 0]

    def gbfs(r, c, dist, chk=False):
        for i in range(n):
            dist[i][:] = [-1]*n
        dist[r][c] = 0
        q = deque()
        q.append((r, c))
        while q:
            p = q.popleft()
            if chk and dist[p[0]][p[1]] == tim[p[0]][p[1]]:
                continue
            for k in range(4):
                r2 = p[0] + dx[k]
                c2 = p[1] + dy[k]
