                if dist[r2][c2] != -1 or obs[r2][c2]:
                    continue
                if chk and tim[r2][c2] > -1 and dist[p[0]][p[1]] + 1 > tim[r2][c2]:
                    continue
                dist[r2][c2] = dist[p[0]][p[1]] + 1
                q.append((r2, c2))

