    m = int(first_line[1])
    lines = data[1:]
    first_grid = [list(line.rstrip()) for line in lines[:n]]
    second_grid = [list(line.rstrip()) for line in lines[n:2*n]]

    def enc(x, y, t):
        return x + y * n + t * n * n + 2

    vn = enc(n - 1, n - 1, m) + 1
    edge = [dict() for _ in range(vn)]

    # source edges from first grid
    for i in range(n):
        for j in range(n):
            c = first_grid[i][j]
            if '1' <= c <= '9':
                u = 0
                v = enc(i, j, 0)
                edge[u][v] = int(c)

    buf = second_grid
    tox = [[m + 1] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if buf[i][j] == 'Z':
                tox[i][j] = 0

    dx = [-1, 0, 1, 0]
    dy = [0, -1, 0, 1]
    q = deque()
    for i in range(n):
        for j in range(n):
            if buf[i][j] == 'Z':
                q.append((i, j))
    while q:
        i, j = q.popleft()
        t = tox[i][j]
        for d in range(4):
            x = i + dx[d]
            y = j + dy[d]
            if 0 <= x < n and 0 <= y < n and buf[x][y] != 'Y' and t + 1 < tox[x][y]:
                tox[x][y] = t + 1
                q.append((x, y))

    # build flow network from second grid
    for i in range(n):
        for j in range(n):
            for t in range(m):
                # edges to neighbors
                for d in range(4):
                    x = i + dx[d]
                    y = j + dy[d]
                    if 0 <= x < n and 0 <= y < n and buf[x][y] != 'Y':
                        extra = 1 if '1' <= buf[x][y] <= '9' else 0
                        if t + 1 < tox[x][y] + extra and t < tox[i][j]:
                            u = enc(i, j, t)
                            v = enc(x, y, t + 1)
                            edge[u][v] = 1000
                # edge to intermediate node
                if '1' <= buf[i][j] <= '9':
                    u = enc(i, j, t)
                    v = enc(i, j, m)
                    edge[u][v] = int(buf[i][j])
            # edge from intermediate node to sink
            if '1' <= buf[i][j] <= '9':
                u = enc(i, j, m)
                v = 1
                edge[u][v] = int(buf[i][j])

    def aug(s, t, cap):
        result = 0
        while True:
            from_ = [-1] * vn
            flow_ = [0] * vn
            from_[s] = s
            flow_[s] = cap
            q = deque([s])
            found = False
            while q:
                x = q.popleft()
                if x == t:
                    aug_flow = flow_[t]
                    result += aug_flow
                    v = t
                    while v != s:
                        u = from_[v]
                        edge[u][v] -= aug_flow
                        if edge[u][v] == 0:
                            del edge[u][v]
                        edge[v][u] = edge[v].get(u, 0) + aug_flow
                        v = u
                    found = True
                    break
                for nxt, cap_edge in edge[x].items():
                    if cap_edge >= cap and from_[nxt] == -1:
                        from_[nxt] = x
                        flow_[nxt] = min(cap_edge, flow_[x])
                        q.append(nxt)
            if not found:
                break
        return result

    res = 0
    for cap in [8, 4, 2, 1]:
        res += aug(0, 1, cap)
    print(res)

if __name__ == "__main__":
