import sys
from collections import deque

INF = 10**9

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    first = data[0].split()
    N = int(first[0])
    T = int(first[1])
    grid1 = [list(data[i+1].strip()) for i in range(N)]
    grid2 = [list(data[i+1+N].strip()) for i in range(N)]

    # Directions
    dx = [-1, 1, 0, 0]
    dy = [0, 0, -1, 1]

    # A[x][y] = distance from nearest 'Z' (or INF)
    A = [[INF]*N for _ in range(N)]
    q = deque()
    for x in range(N):
        for y in range(N):
            if grid1[x][y] == 'Z':
                for d in range(4):
                    nx, ny = x+dx[d], y+dy[d]
                    if 0 <= nx < N and 0 <= ny < N and grid1[nx][ny] != 'Y':
                        A[nx][ny] = 1
                        q.append((nx, ny))
    while q:
        x, y = q.popleft()
        for d in range(4):
            nx, ny = x+dx[d], y+dy[d]
            if 0 <= nx < N and 0 <= ny < N and grid1[nx][ny] != 'Y' and grid1[nx][ny] != 'Z' and A[nx][ny] == INF:
                A[nx][ny] = A[x][y] + 1
                q.append((nx, ny))

    # B[x1][y1][x2][y2] = 1 if there is a safe path within T steps
    B = [[[[0]*N for _ in range(N)] for _ in range(N)] for _ in range(N)]
    for x1 in range(N):
        for y1 in range(N):
            if grid1[x1][y1] in ('Y','Z'):
                continue
            for x2 in range(N):
                for y2 in range(N):
                    if grid1[x2][y2] in ('Y','Z'):
                        continue
                    # BFS from (x1,y1) to (x2,y2)
                    depth = [[INF]*N for _ in range(N)]
                    q2 = deque()
                    depth[x1][y1] = 0
                    q2.append((x1, y1))
                    found = False
                    while q2:
                        x, y = q2.popleft()
                        if x == x2 and y == y2:
                            found = True
                            break
                        if depth[x][y] >= T or depth[x][y] >= A[x][y]:
                            continue
                        for d in range(4):
                            nx, ny = x+dx[d], y+dy[d]
                            if 0 <= nx < N and 0 <= ny < N and grid1[nx][ny] not in ('Y','Z') and depth[nx][ny] == INF and depth[x][y]+1 <= A[nx][ny]:
                                depth[nx][ny] = depth[x][y] + 1
                                q2.append((nx, ny))
                    B[x1][y1][x2][y2] = 1 if found else 0

    # Build flow network
    # Node ids: source = 0, sink = 2*N*N+1
    # For cell (i,j): first layer id = 1 + i*N + j, second layer id = N*N+1 + i*N + j
    total_nodes = 2*N*N + 2
    s = 0
    t = 2*N*N + 1
    e = []  # list of edges: [a, b, cap, flow]
    g = [[] for _ in range(total_nodes)]

    def add_edge(a, b, cap):
        e.append([a, b, cap, 0])
        g[a].append(len(e)-1)
        e.append([b, a, 0, 0])
        g[b].append(len(e)-1)

    # Source to first layer
    for i in range(N):
        for j in range(N):
            if '1' <= grid1[i][j] <= '9':
                cap = int(grid1[i][j])
                node = 1 + i*N + j
                add_edge(s, node, cap)
    # Second layer to sink
    for i in range(N):
        for j in range(N):
            if '1' <= grid2[i][j] <= '9':
                cap = int(grid2[i][j])
                node = N*N + 1 + i*N + j
                add_edge(node, t, cap)
    # Edges from first layer to second layer based on B
    for x1 in range(N):
        for y1 in range(N):
            for x2 in range(N):
                for y2 in range(N):
                    if B[x1][y1][x2][y2]:
                        u = 1 + x1*N + y1
                        v = N*N + 1 + x2*N + y2
                        add_edge(u, v, INF)

    # Dinic max flow
    n = total_nodes
    d = [0]*n
    ptr = [0]*n

    def bfs():
        for i in range(n):
            d[i] = -1
        d[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for idx in g[v]:
                to = e[idx][1]
                if d[to] == -1 and e[idx][2] > e[idx][3]:
                    d[to] = d[v] + 1
                    q.append(to)
        return d[t] != -1

    def dfs(v, flow):
        if flow == 0:
            return 0
        if v == t:
            return flow
        while ptr[v] < len(g[v]):
            idx = g[v][ptr[v]]
            to = e[idx][1]
            if d[to] == d[v] + 1:
                pushed = dfs(to, min(flow, e[idx][2] - e[idx][3]))
                if pushed:
                    e[idx][3] += pushed
                    e[idx^1][3] -= pushed
                    return pushed
            ptr[v] += 1
        return 0

    flow = 0
    while bfs():
        for i in range(n):
            ptr[i] = 0
        while True:
            pushed = dfs(s, INF)
            if not pushed:
                break
            flow += pushed

    print(flow)

if __name__ == "__main__":
    solve()

