from collections import deque

N = 12
INF = 1000000009
dx = [0, 1, 0, -1]
dy = [1, 0, -1, 0]

def bfs(dist, sx, sy, a, n):
    c = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            dist[i][j] = INF
    q = deque()
    c[sx][sy] = True
    dist[sx][sy] = 0
    q.append((sx, sy))
    while q:
        x, y = q.popleft()
        for i in range(4):
            hx = x + dx[i]
            hy = y + dy[i]
            if 0 <= hx < n and 0 <= hy < n and not c[hx][hy] and '0' <= a[hx][hy] <= '9':
                c[hx][hy] = True
                dist[hx][hy] = dist[x][y] + 1
                q.append((hx, hy))

def bfs1(g, nn):
    c = [False]*(nn+2)
    p = [0]*(nn+2)
    q = deque()
    c[0] = True
    q.append(0)
    while q:
        x = q.popleft()
        if x == nn+1:
            return True, p
        for h in range(nn+2):
            if g[x][h] > 0 and not c[h]:
                c[h] = True
                p[h] = x
                q.append(h)
    return False, p

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    t = int(next(it))
