    sy = int(next(it))

    for i in range(n):
        for j in range(n):
            if a[i][j] == 'Z':
                sx = i
                sy = j

    v = [[0]*n for _ in range(n)]
    bfs(v, sx, sy, a, n)

    # dp[yt][sx][sy][x][y] but we only need up to t, and we compress by using set of states
    # Actually we need to follow the original logic precisely. We'll use 4D boolean for current yt.
    dp_cur = [[[[False]*n for _ in range(n)] for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if '0' <= a[i][j] <= '9':
                dp_cur[i][j][i][j] = True

    dp_states = [None]*(t+1)
    dp_states[0] = dp_cur

    for yt in range(t):
