                                if v[hx][hy] >= yt+1:
                                    dp_next[sx][sy][hx][hy] = True
        dp_cur = dp_next
        dp_states[yt+1] = dp_cur

    u = [[[[False]*n for _ in range(n)] for _ in range(n)] for _ in range(n)]
    for yt in range(t+1):
        for sx in range(n):
            for sy in range(n):
                for x in range(n):
                    for y in range(n):
                        if dp_states[yt][sx][sy][x][y]:
                            u[sx][sy][x][y] = True

    nn = 2*n*n
    g = [[0]*(nn+2) for _ in range(nn+2)]

    for x1 in range(n):
        for y1 in range(n):
            if '0' <= a[x1][y1] <= '9':
                g[0][x1*n + y1 + 1] = int(a[x1][y1])

    for x2 in range(n):
        for y2 in range(n):
            if '0' <= b[x2][y2] <= '9':
                g[n*n + x2*n + y2 + 1][nn+1] = int(b[x2][y2])

    for x1 in range(n):
        for y1 in range(n):
            if not ('0' <= a[x1][y1] <= '9'):
                continue
            for x2 in range(n):
                for y2 in range(n):
                    if not ('0' <= a[x2][y2] <= '9'):
                        continue
                    if u[x1][y1][x2][y2]:
                        g[x1*n + y1 + 1][n*n + x2*n + y2 + 1] = INF

