import sys
import collections

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    first = data[0].split()
    n = int(first[0])
    t = int(first[1])
    a = [list(line.rstrip()) for line in data[1:1+n]]
    b = [list(line.rstrip()) for line in data[1+n:1+2*n]]

    INF = 10**9
    # distance to nearest 'Z'
    Dis = [[INF]*n for _ in range(n)]
    q = collections.deque()
    for i in range(n):
        for j in range(n):
            if a[i][j] == 'Z':
                Dis[i][j] = 0
                q.append((i,j))
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    while q:
        x,y = q.popleft()
        for dx,dy in dirs:
            nx,ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < n and '0' <= a[nx][ny] <= '9':
                if Dis[nx][ny] > Dis[x][y] + 1:
                    Dis[nx][ny] = Dis[x][y] + 1
                    q.append((nx,ny))

    # node mapping
    source = 0
    sink = 1
    def src_node(i,j):
        return 2 + i*n + j
    def sink_node(i,j):
        return 2 + n*n + i*n + j
    N = 2 + 2*n*n
    graph = [[] for _ in range(N)]

    def add_edge(u,v,cap):
        graph[u].append([v, len(graph[v]), cap])
        graph[v].append([u, len(graph[u])-1, 0])

    # source to source-side nodes
    for i in range(n):
        for j in range(n):
            if '0' <= a[i][j] <= '9':
                add_edge(source, src_node(i,j), int(a[i][j]))

    # sink-side nodes to sink
    for i in range(n):
        for j in range(n):
            if '0' <= b[i][j] <= '9':
                add_edge(sink_node(i,j), sink, int(b[i][j]))

    # BFS from each source cell and add edges
    for si in range(n):
        for sj in range(n):
            if not ('0' <= a[si][sj] <= '9'):
                continue
            dist = [[INF]*n for _ in range(n)]
            dist[si][sj] = 0
            q = collections.deque()
            q.append((si,sj))
            while q:
                x,y = q.popleft()
                d = dist[x][y]
                if d >= Dis[x][y]:
                    continue
                for dx,dy in dirs:
                    nx,ny = x+dx, y+dy
                    if 0 <= nx < n and 0 <= ny < n and '0' <= a[nx][ny] <= '9':
                        if dist[nx][ny] > d + 1:
                            dist[nx][ny] = d + 1
                            q.append((nx,ny))
            for ti in range(n):
                for tj in range(n):
                    if '0' <= a[ti][tj] <= '9':
                        if dist[ti][tj] <= min(Dis[ti][tj], t):
                            add_edge(src_node(si,sj), sink_node(ti,tj), 10000)

    # Dinic
    level = [-1]*N
    it = [0]*N

    def bfs():
        for i in range(N):
            level[i] = -1
        q = collections.deque()
        level[source] = 0
        q.append(source)
        while q:
            v = q.popleft()
            for e in graph[v]:
                if e[2] > 0 and level[e[0]] < 0:
                    level[e[0]] = level[v] + 1
                    q.append(e[0])
        return level[sink] >= 0

    def dfs(v, f):
        if v == sink:
            return f
        for i in range(it[v], len(graph[v])):
            it[v] = i
            e = graph[v][i]
            if e[2] > 0 and level[v] < level[e[0]]:
                ret = dfs(e[0], min(f, e[2]))
                if ret:
                    e[2] -= ret
                    graph[e[0]][e[1]][2] += ret
                    return ret
        return 0

    flow = 0
    while bfs():
        for i in range(N):
            it[i] = 0
        while True:
            pushed = dfs(source, INF)
            if not pushed:
                break
            flow += pushed
    print(flow)

if __name__ == "__main__":
    solve()

