import sys
from collections import deque

class Dinic:
    def __init__(self, n, src, dst):
        self.n = n
        self.src = src
        self.dst = dst
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        # forward edge
        self.graph[u].append([v, cap, len(self.graph[v])])
        # reverse edge
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def _bfs(self):
        level = [-1] * self.n
        q = deque([self.src])
        level[self.src] = 0
        while q:
            u = q.popleft()
            for v, cap, rev in self.graph[u]:
                if cap > 0 and level[v] == -1:
                    level[v] = level[u] + 1
                    q.append(v)
        self.level = level
        return level[self.dst] != -1

    def _dfs(self, u, f):
        if u == self.dst:
            return f
        for i in range(self.it[u], len(self.graph[u])):
            self.it[u] = i
            v, cap, rev = self.graph[u][i]
            if cap > 0 and self.level[v] == self.level[u] + 1:
                ret = self._dfs(v, min(f, cap))
                if ret:
                    # update forward edge
                    self.graph[u][i][1] -= ret
                    # update reverse edge
                    self.graph[v][rev][1] += ret
                    return ret
        return 0

    def max_flow(self):
        flow = 0
        INF = 10**9
        while self._bfs():
            self.it = [0] * self.n
            while True:
                f = self._dfs(self.src, INF)
                if f == 0:
                    break
                flow += f
        return flow


def solve():
    data = sys.stdin.read().splitlines()
    idx = 0
    out_lines = []
    while idx < len(data):
        line = data[idx].strip()
        if not line:
            idx += 1
            continue
        parts = line.split()
        if len(parts) < 2:
            idx += 1
            continue
        n = int(parts[0])
        t = int(parts[1])
        idx += 1
        smp = []
        for _ in range(n):
            smp.append(list(data[idx].strip()))
            idx += 1
        cmp = []
        for _ in range(n):
            cmp.append(list(data[idx].strip()))
            idx += 1

        # node indices
        def X(i, j):
            return i * n + j
        def Y(i, j):
            return n * n + i * n + j
        S = 2 * n * n
        T = S + 1
        N = T + 1

        dinic = Dinic(N, S, T)

        # add source edges
        for i in range(n):
            for j in range(n):
                ch = smp[i][j]
                if ch.isdigit() and ch > '0':
                    dinic.add_edge(S, X(i, j), ord(ch) - ord('0'))
                elif ch == 'Z':
                    zx, zy = i, j

        # add sink edges
        for i in range(n):
            for j in range(n):
                ch = cmp[i][j]
                if ch.isdigit() and ch > '0':
                    dinic.add_edge(Y(i, j), T, ord(ch) - ord('0'))

        # BFS for each source cell
        dx = [1, 0, -1, 0]
        dy = [0, -1, 0, 1]
        INF = 10**9

        for i in range(n):
            for j in range(n):
                if not (smp[i][j].isdigit() and smp[i][j] > '0'):
                    continue
                # copy smp to work
                work = [row[:] for row in smp]
                vis = [[False] * n for _ in range(n)]
                q = deque()
                # source start
                q.append((i, j, 0, 0))
                vis[i][j] = True
                # zombie start
                q.append((zx, zy, 0, 1))
                while q:
                    x, y, time, typ = q.popleft()
                    if time == t:
                        break
                    if typ == 0:
                        # source type
                        if work[x][y].isalpha():
                            continue
                        for d in range(4):
                            nx = x + dx[d]
                            ny = y + dy[d]
                            if 0 <= nx < n and 0 <= ny < n:
                                if not vis[nx][ny] and not work[nx][ny].isalpha():
                                    vis[nx][ny] = True
                                    q.append((nx, ny, time + 1, 0))
                    else:
                        # zombie type
                        for d in range(4):
                            nx = x + dx[d]
                            ny = y + dy[d]
                            if 0 <= nx < n and 0 <= ny < n:
                                if not work[nx][ny].isalpha():
                                    work[nx][ny] = 'Z'
                                    q.append((nx, ny, time + 1, 1))
                # add edges to reachable sinks
                for xi in range(n):
