import sys
from collections import deque

INF = 0x3f3f3f3f
N = 210

b = [(0, 1), (0, -1), (1, 0), (-1, 0)]

def solve():
    global n, t, st, ed, cap, sci, maze, head, cnt, vis, dp
    n, t = map(int, sys.stdin.readline().split())
    sci = [[0] * (n + 1) for _ in range(n + 1)]
    cap = [[0] * (n + 1) for _ in range(n + 1)]
    maze = [[[0] * (n + 1) for _ in range(n + 1)] for _ in range(t + 1)]
    st = N - 1
    ed = st - 1

    for i in range(1, n + 1):
        line = sys.stdin.readline().strip()
        for j in range(1, n + 1):
            ch = line[j - 1]
            if ch.isdigit():
                sci[i][j] = int(ch)
            elif ch == 'Y':
                maze[0][i][j] = 1
            elif ch == 'Z':
                maze[0][i][j] = 2

    for i in range(1, n + 1):
        line = sys.stdin.readline().strip()
        for j in range(1, n + 1):
            ch = line[j - 1]
            if ch.isdigit():
                cap[i][j] = int(ch)

    head = [-1] * N
    cnt = 0
    edge = []

    def add_edge(u, v, w):
        nonlocal cnt
        edge.append([v, w, head[u]])
        head[u] = cnt
        cnt += 1
        edge.append([u, 0, head[v]])
        head[v] = cnt
        cnt += 1

    now = [0] * N
    d = [0] * N

    def bfs(s, t):
        nonlocal d, now
        d = [0] * N
        q = deque()
        q.append(s)
        now[s] = head[s]
        d[s] = 1
        while q:
            u = q.popleft()
            i = head[u]
            while i != -1:
                v = edge[i][0]
                w = edge[i][1]
                if d[v] == 0 and w:
                    d[v] = d[u] + 1
                    now[v] = head[v]
                    q.append(v)
                    if v == t:
                        return True
                i = edge[i][2]
        return False

    def dinic(x, t, flow):
        if x == t:
            return flow
        rest = flow
        i = now[x]
        while i != -1 and rest:
            v = edge[i][0]
            w = edge[i][1]
            if w and d[v] == d[x] + 1:
                k = dinic(v, t, min(rest, w))
                if k == 0:
                    d[v] = 0
                edge[i][1] -= k
                edge[i ^ 1][1] += k
                rest -= k
            i = edge[i][2]
        now[x] = i
        return flow - rest

    def flow(s, t):
        ans = 0
        while bfs(s, t):
            while True:
                push = dinic(s, t, INF)
                if push == 0:
                    break
                ans += push
        return ans

    def get_id(x, y, k):
        return (x - 1) * n + y + k * n * n

    vis = [[False] * (n + 1) for _ in range(n + 1)]
    dp = [[[[[False] * (n + 1) for _ in range(n + 1)] for _ in range(n + 1)] for _ in range(n + 1)] for _ in range(t + 1)]

