        dp[step][x][y][xx][yy] = True
        if step >= t or maze[step][xx][yy]:
            return
        for k in range(4):
            nx = xx + b[k][0]
            ny = yy + b[k][1]
            if nx <= 0 or ny <= 0 or nx > n or ny > n:
                continue
            if vis[nx][ny]:
                continue
            if maze[step][nx][ny]:
                continue
            dfs(x, y, nx, ny, step + 1)

    def init():
