            for x in range(1, n + 1):
                for y in range(1, n + 1):
                    if maze[time - 1][x][y]:
                        maze[time][x][y] = maze[time - 1][x][y]
                    else:
                        for k in range(4):
                            xx = x + b[k][0]
                            yy = y + b[k][1]
                            if xx <= 0 or yy <= 0 or xx > n or yy > n:
                                continue
                            if maze[time - 1][xx][yy] == 2:
                                maze[time][x][y] = 2
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if sci[i][j]:
                    for xi in range(1, n + 1):
                        for xj in range(1, n + 1):
                            vis[xi][xj] = False
                    dfs(i, j, i, j, 0)
        for i in range(1, t + 1):
            for x in range(1, n + 1):
                for y in range(1, n + 1):
                    for xx in range(1, n + 1):
                        for yy in range(1, n + 1):
                            dp[i][x][y][xx][yy] = dp[i][x][y][xx][yy] or dp[i - 1][x][y][xx][yy]

    init()

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if sci[i][j]:
                add_edge(st, get_id(i, j, 0), sci[i][j])
            if cap[i][j]:
