import sys
from collections import deque

INF = 10**9

def solve() -> None:
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    t = int(next(it))

    # read s1
    s1 = []
    for _ in range(n):
        s1.append(next(it).strip())

    # read s2
    s2 = []
    for _ in range(n):
        s2.append(next(it).strip())

    # dp: distance to nearest 'Z' (before time limit)
    dp = [[-1] * n for _ in range(n)]
    q = deque()
    for i in range(n):
        for j in range(n):
            if s1[i][j] == 'Z':
                dp[i][j] = 0
                q.append((i, j))
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        uy, ux = q.popleft()
        for dy, dx in dirs:
            vy, vx = uy + dy, ux + dx
            if 0 <= vy < n and 0 <= vx < n and s1[vy][vx] != 'Y' and dp[vy][vx] == -1:
                dp[vy][vx] = dp[uy][ux] + 1
                q.append((vy, vx))
    # set unreachable or >t to INF
    for i in range(n):
        for j in range(n):
            if dp[i][j] == -1 or dp[i][j] > t:
                dp[i][j] = INF

    # compute node ids: time layer 0 .. t+1, each n*n nodes, total nodes = (t+2)*n*n + 2
    num_layers = t + 2
    max_id = num_layers * n * n
    source = 0
    sink = max_id + 1
    total_nodes = max_id + 2

    # idx[time][i][j] = node id (1-indexed)
    idx = [[[0]*n for _ in range(n)] for __ in range(num_layers)]
    cur_id = 1
    for time in range(num_layers):
        for i in range(n):
            for j in range(n):
                idx[time][i][j] = cur_id
                cur_id += 1
    # cur_id after loops = max_id+1

    # Dinic implementation
    # graph: list of list of edges, each edge is [to, rev, cap]
    graph = [[] for _ in range(total_nodes)]

    def add_edge(u, v, cap):
        graph[u].append([v, len(graph[v]), cap])
        graph[v].append([u, len(graph[u]) - 1, 0])

    # source to time 0 nodes (s1 digits)
    for i in range(n):
        for j in range(n):
            ch = s1[i][j]
            if '1' <= ch <= '9':
                add_edge(source, idx[0][i][j], ord(ch) - ord('0'))

    # edges between layers for moves
    for i in range(n):
        for j in range(n):
            if s1[i][j] in ('Y', 'Z'):
                continue
            # for each direction
            for dy, dx in dirs:
                vy = i + dy
                vx = j + dx
                if 0 <= vy < n and 0 <= vx < n and s1[vy][vx] not in ('Y', 'Z'):
                    # for each time step from 0 to t-1
                    for x in range(t):
                        if dp[vy][vx] >= x + 1 and dp[i][j] > x:
                            add_edge(idx[x][i][j], idx[x+1][vy][vx], 1000)

    # edges from each time layer to the t+1 layer (sink connections via s2)
    for i in range(n):
        for j in range(n):
            if s1[i][j] in ('Y', 'Z'):
                continue
            ch = s2[i][j]
            if '1' <= ch <= '9':
                cap = ord(ch) - ord('0')
                # for each time x from 0 to t
                for x in range(t + 1):
                    add_edge(idx[x][i][j], idx[t+1][i][j], cap)
                # also from t+1 to sink
                add_edge(idx[t+1][i][j], sink, cap)

    # Dinic max flow
    N = total_nodes
    level = [0] * N
    it_ptr = [0] * N

    def bfs():
        for i in range(N):
            level[i] = -1
        q = deque([source])
        level[source] = 0
        while q:
            u = q.popleft()
            for v, rev, cap in graph[u]:
                if cap > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        return level[sink] >= 0

    def dfs(u, flow):
        if u == sink:
            return flow
        for i in range(it_ptr[u], len(graph[u])):
            it_ptr[u] = i
            v, rev, cap = graph[u][i]
            if cap > 0 and level[v] == level[u] + 1:
                ret = dfs(v, min(flow, cap))
                if ret > 0:
                    # update residual capacities
                    graph[u][i][2] -= ret
                    graph[v][rev][2] += ret
                    return ret
        return 0

    max_flow = 0
    while bfs():
        for i in range(N):
            it_ptr[i] = 0
        while True:
            pushed = dfs(source, INF)
            if not pushed:
                break
            max_flow += pushed

    sys.stdout.write(str(max_flow))

if __name__ == '__main__':
    solve()

