import sys
from collections import deque

class NetworkFlow:
    def __init__(self, V, s, t):
        self.adj = [[] for _ in range(V)]
        self.lev = [0] * V
        self.edge_tried = [0] * V
        self.st = s
        self.ed = t

    def set_edge(self, u, v, fl):
        sz1 = len(self.adj[v])
        sz2 = len(self.adj[u])
        self.adj[u].append([v, fl, sz1])
        self.adj[v].append([u, 0, sz2])

    def assign_level(self):
        self.lev = [-1] * len(self.adj)
        self.lev[self.st] = 0
        q = deque([self.st])
        while q:
            now = q.popleft()
            for nxt, w, rev in self.adj[now]:
                if self.lev[nxt] == -1 and w != 0:
                    self.lev[nxt] = self.lev[now] + 1
                    q.append(nxt)
        return self.lev[self.ed] != -1

    def dfs(self, now, fl):
        if now == self.ed:
            return fl
        i = self.edge_tried[now]
        while i < len(self.adj[now]):
            nxt, w, rev = self.adj[now][i]
            if self.lev[nxt] == self.lev[now] + 1 and w != 0:
                nxtflow = self.dfs(nxt, min(fl, w))
                if nxtflow:
                    self.adj[now][i][1] -= nxtflow
                    self.adj[nxt][rev][1] += nxtflow
                    return nxtflow
            i += 1
            self.edge_tried[now] = i
        return 0

    def dinic(self):
        ret = 0
        while self.assign_level():
            self.edge_tried = [0] * len(self.adj)
            while True:
                amt = self.dfs(self.st, 10**9)
                if amt == 0:
                    break
                ret += amt
        return ret

def main():
