    if not data:
        return
    first = data[0].split()
    n = int(first[0])
    ti = int(first[1])
    str_grid = []
    idx = 1
    for i in range(n):
        str_grid.append(data[idx].strip())
        idx += 1
    # skip two lines (blank lines)
    idx += 2  # because there are two getline calls in C++ (they read empty lines)
    es_grid = []
    for i in range(n):
        es_grid.append(data[idx].strip())
        idx += 1

    # find start 'Z'
    yy = xx = -1
    for i in range(n):
        for j in range(n):
            if str_grid[i][j] == 'Z':
                yy, xx = i, j
                break
        if yy != -1:
            break

    # BFS to compute ck (distance from start, capped at ti)
    ck = [[0]*n for _ in range(n)]
    dy = [1, -1, 0, 0]
    dx = [0, 0, 1, -1]
    q = deque()
