import sys
from collections import deque

INF = 10**9

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        # forward edge
        self.adj[u].append([v, cap, len(self.adj[v])])
        # backward edge
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])

    def bfs(self, s, t, level):
        for i in range(self.n):
            level[i] = -1
        q = deque()
        level[s] = 0
        q.append(s)
        while q:
            u = q.popleft()
            for v, cap, rev in self.adj[u]:
                if cap > 0 and level[v] == -1:
                    level[v] = level[u] + 1
                    q.append(v)
        return level[t] != -1

    def dfs(self, u, t, f, level, it):
        if u == t:
            return f
        for i in range(it[u], len(self.adj[u])):
            it[u] = i
            v, cap, rev = self.adj[u][i]
            if cap > 0 and level[v] == level[u] + 1:
                ret = self.dfs(v, t, min(f, cap), level, it)
                if ret > 0:
                    # update forward edge
                    self.adj[u][i][1] -= ret
                    # update backward edge
                    self.adj[v][rev][1] += ret
                    return ret
        return 0

    def max_flow(self, s, t):
        flow = 0
        level = [-1] * self.n
        it = [0] * self.n
        while self.bfs(s, t, level):
            for i in range(self.n):
                it[i] = 0
            while True:
                f = self.dfs(s, t, INF, level, it)
                if f == 0:
                    break
                flow += f
        return flow

def main():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    n = int(next(it))
    t = int(next(it))
    g = []
    for _ in range(n):
        g.append(next(it).decode())
    h = []
    for _ in range(n):
        h.append(next(it).decode())

    # directions
    dx = [-1, 0, 1, 0]
    dy = [0, 1, 0, -1]

    def in_bounds(x, y):
        return 0 <= x < n and 0 <= y < n

    # tim array for bfs1
    tim = [[INF]*n for _ in range(n)]
    # bfs1 from each 'Z' (only last one matters due to overwriting)
    for i in range(n):
        for j in range(n):
            if g[i][j] == 'Z':
                # reset tim
                for ii in range(n):
                    for jj in range(n):
                        tim[ii][jj] = INF
                q = deque()
                q.append((i, j))
                tim[i][j] = 0
                while q:
                    x, y = q.popleft()
                    for k in range(4):
                        nx = x + dx[k]
                        ny = y + dy[k]
                        if in_bounds(nx, ny) and '0' <= g[nx][ny] <= '9' and tim[nx][ny] > tim[x][y] + 1:
                            tim[nx][ny] = tim[x][y] + 1
                            q.append((nx, ny))

    # Build graph
    S = 0
    T = n * n * 2 + 1
    dinic = Dinic(T + 1)

    # Add edges from source to g cells
    for i in range(n):
        for j in range(n):
            if '0' < g[i][j] <= '9':
                cap = ord(g[i][j]) - ord('0')
