        line = next(it)
        for j, ch in enumerate(line, 1):
            if '0' <= ch <= '9':
                ca[i][j] = int(ch)

    # expand stones
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for k in range(1, t+1):
        for i in range(1, n+1):
            for j in range(1, n+1):
                if stone[k-1][i][j] == 1:
                    stone[k][i][j] = 1
                elif stone[k-1][i][j] == 2:
                    stone[k][i][j] = 2
                else:
                    for dx, dy in dirs:
                        ni, nj = i+dx, j+dy
                        if 1 <= ni <= n and 1 <= nj <= n:
                            if stone[k-1][ni][nj] == 2:
                                stone[k][i][j] = 2
                                break

    # dp[k][x][y][nx][ny] - reachable within k steps
    dp = [[[[[0]*(n+1) for _ in range(n+1)] for _ in range(n+1)] for _ in range(n+1)] for __ in range(t+1)]

    vis = [[0]*(n+2) for _ in range(n+2)]

    def dfs(x, y, nowx, nowy, k):
        vis[nowx][nowy] = 1
        dp[k][x][y][nowx][nowy] = 1
        if k >= t or stone[k][nowx][nowy]:
            return
        for dx, dy in dirs:
            nx, ny = nowx+dx, nowy+dy
            if 1 <= nx <= n and 1 <= ny <= n and not vis[nx][ny]:
                if stone[k][nx][ny]:
                    continue
                dfs(x, y, nx, ny, k+1)

    for i in range(1, n+1):
        for j in range(1, n+1):
            if sci[i][j]:
                # reset vis
                for ii in range(1, n+1):
                    for jj in range(1, n+1):
                        vis[ii][jj] = 0
                dfs(i, j, i, j, 0)

    # accumulate dp over time
    for k in range(1, t+1):
        for x in range(1, n+1):
            for y in range(1, n+1):
                for nx in range(1, n+1):
                    for ny in range(1, n+1):
                        dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny]

    # build flow network
    S = 0
    T = n*n*2 + 1
    node_count = T + 1

    head = [-1] * node_count
    adj = []
    edge = []  # each edge: [v, w]
    e = 0

    def add_edge(u, v, w):
        nonlocal e
        edge.append([v, w])
        adj.append(head[u])
        head[u] = e
        e += 1
        edge.append([u, 0])
        adj.append(head[v])
        head[v] = e
        e += 1

    # source to scientist nodes
    for i in range(1, n+1):
        for j in range(1, n+1):
            if sci[i][j]:
                node = (i-1)*n + j
                add_edge(S, node, sci[i][j])

    # capacity nodes to sink
    for i in range(1, n+1):
        for j in range(1, n+1):
            if ca[i][j]:
                node = n*n + (i-1)*n + j
                add_edge(node, T, ca[i][j])

    # scientist to capacity edges if reachable within t steps
    for x in range(1, n+1):
        for y in range(1, n+1):
            if sci[x][y]:
                for nx in range(1, n+1):
                    for ny in range(1, n+1):
                        if ca[nx][ny] and dp[t][x][y][nx][ny]:
                            u = (x-1)*n + y
                            v = n*n + (nx-1)*n + ny
                            add_edge(u, v, INF)

    # SAP max flow
    def sap(s, t):
        dist = [-1] * node_count
        gap = [0] * (node_count + 2)
        inq = [0] * node_count
        pre = [-1] * node_count
        arc = head[:]  # copy

        # BFS from sink
        q = deque()
        q.append(t)
        inq[t] = 1
        gap[0] = 1
        dist[t] = 0
        while q:
            u = q.popleft()
            i = head[u]
            while i != -1:
                v = edge[i][0]
                if not inq[v]:
                    inq[v] = 1
                    dist[v] = dist[u] + 1
                    gap[dist[v]] += 1
                    arc[v] = head[v]
                    q.append(v)
                i = adj[i]

        low = INF
        u = s
        ans = 0
        pre[s] = s
        while dist[s] < t:  # note: original uses t (sink index) as bound
            flag = False
            i = arc[u]
            while i != -1:
                v = edge[i][0]
                if edge[i][1] > 0 and dist[v] + 1 == dist[u]:
                    flag = True
                    low = min(low, edge[i][1])
                    pre[v] = u
                    u = v
                    if u == t:
                        while u != s:
                            u = pre[u]
                            edge[arc[u]][1] -= low
                            edge[arc[u] ^ 1][1] += low
                        ans += low
                        low = INF
                    break
                i = adj[i]
            if flag:
                continue
            mindis = t + 1
            i = head[u]
            while i != -1:
                v = edge[i][0]
                if edge[i][1] > 0 and mindis > dist[v]:
                    mindis = dist[v]
                    arc[u] = i
                i = adj[i]
            gap[dist[u]] -= 1
            if gap[dist[u]] == 0:
                return ans
            dist[u] = mindis + 1
            gap[dist[u]] += 1
            u = pre[u]
        return ans

    ans = sap(S, T)
    print(ans)

if __name__ == "__main__":
    solve()

