            if 0 <= xx < n and 0 <= yy < n and dis[xx][yy] == -1:
                if t[xx][yy] not in ('Y', 'Z'):
                    dis[xx][yy] = dis[x][y] + 1
                    q.append((xx, yy))

    # Replace -1 with INF
    for i in range(n):
