import sys
from collections import deque

INF = 10**9
dx = [1, 0, 0, -1]
dy = [0, 1, -1, 0]

class MaxFlow:
    def __init__(self, n_nodes):
        self.n = n_nodes
        self.graph = [[] for _ in range(n_nodes)]
        self.edges = []  # list of (to, rev, cap, flow)

    def add_edge(self, fr, to, cap):
        forward = [to, len(self.graph[to]), cap, 0]
        backward = [fr, len(self.graph[fr]), 0, 0]
        self.graph[fr].append(len(self.edges))
        self.edges.append(forward)
        self.graph[to].append(len(self.edges))
        self.edges.append(backward)

    def dfs(self, v, t, cur_flow, used):
        if v == t:
            return True
        used[v] = True
        for idx in self.graph[v]:
            to, rev, cap, flow = self.edges[idx]
            if not used[to] and cap - flow >= cur_flow:
                if self.dfs(to, t, cur_flow, used):
                    self.edges[idx][3] += cur_flow
                    self.edges[rev][3] -= cur_flow
                    return True
        return False

    def get_max_flow(self, s, t):
        cur_flow = 1 << 30
        total_flow = 0
        while cur_flow > 0:
            used = [False] * self.n
            if self.dfs(s, t, cur_flow, used):
                total_flow += cur_flow
            else:
                cur_flow >>= 1
        return total_flow

def ok(x, y, n, a):
    return 0 <= x < n and 0 <= y < n and a[x][y] != 'Y' and a[x][y] != 'Z'

def bfs_death(x, y, n, a):
    dist = [[INF] * n for _ in range(n)]
    qx = deque()
    qy = deque()
    dist[x][y] = 0
    qx.append(x)
    qy.append(y)
    while qx:
        cx = qx.popleft()
        cy = qy.popleft()
        for k in range(4):
            tx = cx + dx[k]
            ty = cy + dy[k]
            if ok(tx, ty, n, a) and dist[tx][ty] == INF:
                dist[tx][ty] = dist[cx][cy] + 1
                qx.append(tx)
                qy.append(ty)
    return dist

def run_bfs(x, y, n, t, a, b, dist, max_flow):
    used = [[False] * n for _ in range(n)]
    qx = deque()
    qy = deque()
    qlev = deque()
    used[x][y] = True
    qx.append(x)
    qy.append(y)
    qlev.append(0)
    while qx:
        cx = qx.popleft()
        cy = qy.popleft()
        cur_lev = qlev.popleft()
        if b[cx][cy].isdigit() and b[cx][cy] != '0':
            max_flow.add_edge(x * n + y, n * n + 1 + cx * n + cy, INF)
        if cur_lev >= t:
            continue
        for k in range(4):
            tx = cx + dx[k]
            ty = cy + dy[k]
            if ok(tx, ty, n, a) and not used[tx][ty]:
                if dist[tx][ty] > cur_lev + 1:
                    qx.append(tx)
                    qy.append(ty)
                    qlev.append(cur_lev + 1)
                elif dist[tx][ty] > cur_lev and b[tx][ty].isdigit() and b[tx][ty] != '0':
                    max_flow.add_edge(x * n + y, n * n + 1 + tx * n + ty, INF)
                used[tx][ty] = True

def build(n, t, a, b, max_flow):
    # find Z
    zi = zj = -1
    for i in range(n):
        for j in range(n):
            if a[i][j] == 'Z':
                zi, zj = i, j
                break
        if zi != -1:
            break
    dist = bfs_death(zi, zj, n, a)
    S = n * n * 2  # source index
    T = n * n * 2 + 1  # sink index
    # add edges from source to a-digits
    for i in range(n):
        for j in range(n):
            if a[i][j].isdigit() and a[i][j] != '0':
                max_flow.add_edge(S, i * n + j, int(a[i][j]))
    # add edges from b-digits to sink
    for i in range(n):
        for j in range(n):
            if b[i][j].isdigit() and b[i][j] != '0':
                max_flow.add_edge(i * n + j + n * n + 1, T, int(b[i][j]))
    # add edges from a-cells to b-cells
    for i in range(n):
        for j in range(n):
            if a[i][j].isdigit() and a[i][j] != '0':
                run_bfs(i, j, n, t, a, b, dist, max_flow)
    return S, T

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    first = data[0].split()
    n = int(first[0])
    t = int(first[1])
    a = []
