        self.E.append([v, self.l[u], cap])
        self.l[u] = self.tot
        self.tot += 1
        self.E.append([u, self.l[v], 0])
        self.l[v] = self.tot
        self.tot += 1

    def bfs(self):
        self.d = [-1] * self.N
        self.cur = self.l[:]
        self.d[self.src] = 0
        q = deque([self.src])
        while q:
            u = q.popleft()
            i = self.l[u]
            while i != -1:
                v, _, cap = self.E[i]
                if self.d[v] == -1 and cap > 0:
                    self.d[v] = self.d[u] + 1
                    q.append(v)
                i = self.E[i][1]
        return self.d[self.sink] != -1

    def dfs(self, u, flow_in):
        if u == self.sink:
            return flow_in
        flow = 0
        i = self.cur[u]
        while i != -1:
            v, _, cap = self.E[i]
