def Tabs(n):
    return abs(n)

def solve_it(x, y, b):
    target = x / y
    lb, ub = 0, 1000000
    for _ in range(25):
        a = (lb + ub) // 2
        if a / b < target:
            lb = a
        else:
            ub = a
    res = 0
    diff = float('inf')
    for a in range(lb - 10, ub + 11):
        d = Tabs(a / b - target)
        if d < diff:
            diff = d
            res = a
    return res

