import sys
import math

def gcd(a, b):
    while b:
        a %= b
        a, b = b, a
    return a

class Dro:
    def __init__(self, ch=0, zn=1):
        self.ch = ch
        self.zn = zn

    def __sub__(self, other):
        new_ch = self.ch * other.zn - other.ch * self.zn
        new_zn = self.zn * other.zn
        return Dro(new_ch, new_zn)

    def __lt__(self, other):
        return self.ch * other.zn < other.ch * self.zn

    def cok(self):
        j = gcd(self.ch, self.zn)
        self.ch //= j
        self.zn //= j

    def sho(self):
        print(f"{self.ch}/{self.zn}", end='')

def main():
    #freopen("input.txt", "r", stdin);
    data = sys.stdin.read().strip().split()
    x, y, n = map(int, data)
    os = Dro(50, 1)
    na = Dro(x, y)
    ot = Dro()
    for i in range(1, n+1):
        r = (na.ch * i) // na.zn
        z = (na.ch * i) % na.zn
        if z > (na.zn // 2):
            r += 1
            z = na.zn - z
        p = Dro(z, i * na.zn)
        if p < os:
            os = p
            ot = Dro(r, i)
    ot.sho()

if __name__ == "__main__":
    main()

