        i += 1
    return True

def gcd(x, y):
    return x if y == 0 else gcd(y, x % y)

def FPW(x, y, mod):
    res = 1
    while y:
        if y % 2 == 1:
            res = (res * x) % mod
        x = (x * x) % mod
        y >>= 1
    return res

