		//cout<<"UPD2 "<<di<<' '<<i<<' '<<j<<' '<<ans<<' '<<bas<<' '<<dif[di]<<endl;
		return;
	}
	int mid=(di+i)/2;
	*q1=*q2=0;
	dfs(i+1,mid,q1,bas);
	dfs(mid+1,di,q2,0);
	sort(q2+1,q2+*q2+1);
