	int i = 0;
	while(res*10+1<=n){
		res*=10;
		res++;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res < n){
		res+=resmul;
		i+=imul;
	}
	return {res, i};
}

step lower(ll n){
	ll res = 0;
	int i = 0;
	while(res*10+1<=n){
		res*=10;
		res++;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res+resmul <= n){
		res+=resmul;
		i+=imul;
	}
	return {res, i};
}

int main(int argc, char **argv) {
	ll n;
