def nb_digits(n: int) -> int:
    n = -n if n < 0 else n
    digits = 0
    while n:
        digits += 1
        n //= 10
    return digits

def ones(n: int) -> int:
    res = 0
    for _ in range(n):
        res = 10 * res + 1
    return res

def aux2(n: int) -> int:
    if n == 0:
        return 0
    n = -n if n < 0 else n
    d = nb_digits(n)
    return d + aux2(n - ones(d))

def aux(n: int, sign: int, acc: int, max_val: int, already_in) -> int:
    if acc >= max_val:
        return max_val
    if n == 0:
        return acc
    if n < 0:
        n = -n
        sign = -sign
    d = nb_digits(n)
    ones_d = ones(d)
    res1 = max_val
    res2 = max_val

    if 0 <= already_in[d] * sign and -10 < already_in[d] < 10:
        already_in[d] += sign
        res1 = aux(n - ones_d, sign, acc + d, max_val, already_in)
