import sys

def process(s):
    n = len(s)
    if n == 0:
        return ""
    ans = s[0]
    sw = 0
    i = 1
    while i < n:
        # check for "at"
        if i + 1 < n and s[i] == 'a' and s[i + 1] == 't':
            if i + 1 == n - 1:
                ans += s[i] + s[i + 1]
                i += 1
            else:
                if not sw:
                    i += 1
                    ans += '@'
                    sw = 1
                else:
                    ans += s[i] + s[i + 1]
                    i += 1
            i += 1  # loop increment
            continue
        # check for "dot"
        if i + 2 < n and s[i] == 'd' and s[i + 1] == 'o' and s[i + 2] == 't':
            if i + 2 == n - 1:
                ans += s[i] + s[i + 1] + s[i + 2]
                i += 2
            else:
                i += 2
                ans += '.'
            i += 1  # loop increment
            continue
        ans += s[i]
        i += 1
    return ans

def main():
    data = sys.stdin.read().split()
    for s in data:
        print(process(s))

