import sys

MOD = 1000000007

def modpow(a, e):
    ret = 1
    while e > 0:
        if e & 1:
            ret = (ret * a) % MOD
        a = (a * a) % MOD
        e >>= 1
    return ret

def popcount(x):
    return bin(x).count('1')

def cm(a, comp):
    ret = 0
    for i in range(20):
        if a & (1 << i):
            ret += (1 << comp[i])
    return ret

def main():
    # Precompute m3 and map
    m3 = []
    mp = {}
    for i in range(1 << 6):
        if popcount(i) == 3:
            m3.append(i)
            mp[i] = len(m3) - 1
    comp = [0] * 20
    for i in range(1 << 6):
        if popcount(i) == 3:
            comp[mp[i]] = mp[i ^ 63]
    assert len(mp) == 20

    n_input = int(sys.stdin.readline())
    pr = [[0] * 6 for _ in range(6)]
    for i in range(n_input):
        vals = list(map(int, sys.stdin.readline().split()))
        for j in range(n_input):
            pr[i][j] = (vals[j] * modpow(100, MOD - 2)) % MOD
    for i in range(n_input, 6):
        pr[i][i] = 1
    n = 6

    sub = [[0] * (1 << 18), [0] * (1 << 18)]
    mas = [0] * (1 << 18)
    for mask in range(1 << 18):
        sub[0][mask] = 1
        sub[1][mask] = 1
        for i in range(6):
            for j in range(3):
                bit = mask >> (i * 3 + j) & 1
                # first group (0-2)
                p0 = pr[i][j]
                od0 = (1 - p0) % MOD
                if bit:
                    sub[0][mask] = (sub[0][mask] * p0) % MOD
                else:
                    sub[0][mask] = (sub[0][mask] * od0) % MOD
                # second group (3-5)
                p1 = pr[i][3 + j]
                od1 = (1 - p1) % MOD
                if bit & 1:  # same bit used for both? careful: need separate bit for second group?
                    # Actually the original uses the same mask for both groups.
                    # But the mask layout: bits (i*3+j) for both sub[0] and sub[1] using same mask.
                    # This is correct: the mask bits are reused across groups.
                    pass
                # Let's re-read original: it uses mask bits for both sub[0] and sub[1] equally.
                if bit:
                    sub[1][mask] = (sub[1][mask] * p1) % MOD
                else:
                    sub[1][mask] = (sub[1][mask] * od1) % MOD

