class Mint:
    def __init__(self, v=0):
        self.v = v % MOD

    def __bool__(self):
        return self.v != 0

    def __neg__(self):
        return Mint(0) - self

    def __add__(self, other):
        if isinstance(other, Mint):
            return Mint(self.v + other.v)
        return Mint(self.v + other)

    def __sub__(self, other):
        if isinstance(other, Mint):
            return Mint(self.v + MOD - other.v)
        return Mint(self.v - other)

    def __mul__(self, other):
        if isinstance(other, Mint):
            return Mint(self.v * other.v % MOD)
        return Mint(self.v * other % MOD)

    def __truediv__(self, other):
        return self * other.inv()

    def __iadd__(self, other):
        self.v = (self.v + other.v) % MOD
        return self

    def __isub__(self, other):
        self.v = (self.v + MOD - other.v) % MOD
        return self

