        return self

    def __imul__(self, other):
        self.val = (self.val * other.val) % MOD
        return self

    def __idiv__(self, other):
        return self.__imul__(other.inv())

    def __repr__(self):
        return str(self.val)

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    prob = [[ModInt(0) for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
