import sys

MOD = 1000000007

class Modular:
    def __init__(self, val=0):
        self.val = val % MOD
        if self.val < 0:
            self.val += MOD

    def __add__(self, other):
        res = self.val + (other.val if isinstance(other, Modular) else other)
        if res >= MOD:
            res -= MOD
        return Modular(res)

    def __sub__(self, other):
        res = self.val - (other.val if isinstance(other, Modular) else other)
        if res < 0:
            res += MOD
        return Modular(res)

    def __mul__(self, other):
        other_val = other.val if isinstance(other, Modular) else other
        if other_val == 0:
            return Modular(0)
        if other_val == 1:
            return self
        if other_val == 2:
            return self + self
        if other_val == 3:
            return self + self + self
        if other_val == -1:
            return -self
        res = (self.val * other_val) % MOD
        return Modular(res)

    def __truediv__(self, other):
        return self * other.inv()

    def __neg__(self):
        return Modular(0) - self

    def __eq__(self, other):
        return self.val == (other.val if isinstance(other, Modular) else other)

    def __ne__(self, other):
        return not self.__eq__(other)

    def __lt__(self, other):
        return self.val < (other.val if isinstance(other, Modular) else other)

    def __gt__(self, other):
        return self.val > (other.val if isinstance(other, Modular) else other)

    def __le__(self, other):
        return self.val <= (other.val if isinstance(other, Modular) else other)

    def __ge__(self, other):
        return self.val >= (other.val if isinstance(other, Modular) else other)

    def inv(self):
        a = self.val
        b = MOD
        ax = 1
        bx = 0
        while b:
            q = a // b
            t = a % b
            a = b
            b = t
            t = ax - bx * q
            ax = bx
            bx = t
        if ax < 0:
            ax += MOD
        return Modular(ax)

    def pow(self, p):
        a = self
        ans = Modular(1)
        while p:
            if p & 1:
                ans = ans * a
            a = a * a
            p >>= 1
        return ans

    def __int__(self):
        return self.val

    def __repr__(self):
        return str(self.val)

