using namespace std;
typedef long long ll;
const ll MOD = 1e9+7;
ll add(ll x, ll y) {
	return (x + y) % MOD;
}
ll sub(ll x, ll y) {
	x -= y;
	return (x<0 ? x+MOD : x);
}
ll mult(ll x, ll y) {
	return (x * y) % MOD;
}
ll modpow(ll x, ll p) {
	if (p == 0) return 1;
	if (p & 1) return mult(x, modpow(x, p - 1));
	return modpow(mult(x, x), p>>1);
}
ll modinv(ll x) {
	return modpow(x, MOD-2);
}

int n;
vector<vector<ll>> A;
ll T[8][1<<7][1<<7];
vector<unordered_map<ll,ll>> DP;
vector<int> family(1<<7,0);
vector<int> family_id(1<<7,0);
vector<vector<int>> family_mask;

void calc() {
    family_mask.resize(n+1);
    for (int mask=1; mask<(1<<n); ++mask) {
        family[mask] = family[mask>>1] + (mask & 1);
    }
    for (int mask=0; mask<(1<<n); ++mask) {
        family_id[mask] = (int)family_mask[family[mask]].size();
        family_mask[family[mask]].push_back(mask);
    }
    for (int k=0; k<=n; ++k) {
        for (int i=0; i<(int)family_mask[k].size(); ++i) {
            int cm = family_mask[k][i];
            for (int mask=0; mask<(1<<n); ++mask) {
                ll ans = 0;
                if ((mask & cm) == mask) continue;
                for (int x=0; x<n; ++x) {
                    if (cm & (1<<x)) continue;
                    if ((mask & (1<<x))==0) continue;
                    int newmask = cm | (1<<x);
                    ans |= (1ll << family_id[newmask]);
                }
                T[k][i][mask] = ans;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin>>n;
    A.resize(n);
    for (int i=0; i<n; ++i) {
        A[i].resize(n);
        for (int j=0; j<n; ++j) {
            cin>>A[i][j];
            A[i][j] = mult(A[i][j],modinv(100));
        }
    }
    calc();
    DP.resize(n+1);
    DP[0][1] = 1;
    for (int k=0; k<n; ++k) {
        for (int edges=0; edges<(1<<n); ++edges) {
            ll prob = 1;
            for (int i=0; i<n; ++i) {
                if (edges & (1<<i)) prob = mult(prob, A[k][i]);
                else prob = mult(prob, sub(1,A[k][i]));
            }
            for (auto S : DP[k]) {
                ll mask = S.first;
                ll newmask = 0;
                ll p = mult(prob, S.second);
                for (int i=0; i<(int)family_mask[k].size(); ++i) {
                    if (mask & (1<<i)) {
                        newmask |= T[k][i][edges];
                    }
                }
                if (newmask != 0) DP[k+1][newmask] = add(DP[k+1][newmask], p);
            }
        }
    }
    cout << DP[n][1] << endl;

    return 0;
}

