import sys

MOD = 10**9 + 7

class mod_int:
    __slots__ = ('val',)
    def __init__(self, v=0):
        if isinstance(v, mod_int):
            self.val = v.val
            return
        v = int(v)
        if v < 0:
            v = v % MOD + MOD
        if v >= MOD:
            v %= MOD
        self.val = v

    @staticmethod
    def mod_inv(a, m=MOD):
        g, r = m, a
        x, y = 0, 1
        while r != 0:
            q = g // r
            g, r = r, g - q * r
            x, y = y, x - q * y
        return x if x >= 0 else x + m

    def __int__(self):
        return self.val

    def __iadd__(self, other):
        if isinstance(other, mod_int):
            other = other.val
        self.val += other
        if self.val >= MOD:
            self.val -= MOD
        return self

    def __isub__(self, other):
        if isinstance(other, mod_int):
            other = other.val
        self.val -= other
        if self.val < 0:
            self.val += MOD
        return self

    def __imul__(self, other):
        if isinstance(other, mod_int):
            other = other.val
        self.val = (self.val * other) % MOD
        return self

    def __itruediv__(self, other):
        if isinstance(other, mod_int):
            other = other.val
        inv = mod_int.mod_inv(other)
        self.val = (self.val * inv) % MOD
        return self

    def __add__(self, other):
        res = mod_int(self)
        res += other
        return res

    def __sub__(self, other):
        res = mod_int(self)
        res -= other
        return res

    def __mul__(self, other):
        res = mod_int(self)
        res *= other
        return res

    def __truediv__(self, other):
        res = mod_int(self)
        res /= other
        return res

    def __neg__(self):
        return mod_int(0) if self.val == 0 else mod_int(MOD - self.val)

    def __eq__(self, other):
        if isinstance(other, mod_int):
            return self.val == other.val
        return self.val == other

    def __ne__(self, other):
        return not self.__eq__(other)

    def __repr__(self):
        return str(self.val)

    def inv(self):
        return mod_int(mod_int.mod_inv(self.val))

    def pow(self, p):
        assert p >= 0
        a = mod_int(self)
        result = mod_int(1)
        while p:
            if p & 1:
                result *= a
            a *= a
            p >>= 1
        return result

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    probability = [[mod_int(0) for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            p = int(next(it))
            probability[i][j] = mod_int(p) / mod_int(100)

    masks_with_count = [[] for _ in range(N + 1)]
    lookup = [-1] * (1 << N)
    for mask in range(1 << N):
        cnt = mask.bit_count()
        lookup[mask] = len(masks_with_count[cnt])
        masks_with_count[cnt].append(mask)

    possible_masks = {1 << lookup[0]: mod_int(1)}

    for left in range(N):
        new_possible_masks = {}
        products = [mod_int(1) for _ in range(1 << N)]
        for current in range(1 << N):
            prod = mod_int(1)
            for right in range(N):
                if (current >> right) & 1:
                    prod *= probability[left][right]
                else:
                    prod *= (mod_int(1) - probability[left][right])
            products[current] = prod

        new_bits = [0] * N
        for possible, prob in possible_masks.items():
            # reset new_bits for this possible
            for i in range(N):
                new_bits[i] = 0
            for mask in masks_with_count[left]:
