def mul(a, b):
    return (a * b) % MOD

def power(x, k):
    return pow(x, k, MOD)

def solve():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    inv100 = power(100, MOD - 2)
    a = [[0] * 8 for _ in range(8)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            val = next(it)
            a[i][j] = mul(val, inv100)
    for i in range(n + 1, 7):
        a[i][i] = 1

    g = [[0] * 8 for _ in range(8)]
    num = [[[0] * 8 for _ in range(8)] for _ in range(8)]
    cnt = 0
    for i in range(1, 7):
        for j in range(i + 1, 7):
            for k in range(j + 1, 7):
                num[i][j][k] = 1 << cnt
                cnt += 1
    all_mask = (1 << cnt) - 1
    p = [0] * (1 << cnt)

    def check(x, y, z):
        lis = [x, y, z]
        for perm in itertools.permutations([1, 2, 3]):
