                            used[i] = used[j] = used[k] = False
                            remaining = [l for l in range(1, 7) if used[l]]
                            if len(remaining) == 3:
                                X, Y, Z = remaining
                                sta |= num[X][Y][Z]
                            used[i] = used[j] = used[k] = True
            p[sta] = inc(p[sta], now)
            return
