import sys

MOD = 1000000007
inv100 = pow(100, MOD-2, MOD)

def mod_add(a, b):
    return (a + b) % MOD

def mod_mul(a, b):
    return (a * b) % MOD

def mod_sub(a, b):
    return (a - b) % MOD

def mod_div(a, b):
    return mod_mul(a, pow(b, MOD-2, MOD))

def main():
    input_data = sys.stdin.read().split()
    it = iter(input_data)
    N = int(next(it))
    p = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            val = int(next(it))
            p[i][j] = mod_mul(val, inv100)

    # Precompute for each i: for each e (0..(1<<N)-1), probability pr
    pr_table = []
    for i in range(N):
        pr_e = [0] * (1<<N)
        for e in range(1<<N):
            pr = 1
            for j in range(N):
                if (e >> j) & 1:
                    pr = mod_mul(pr, p[i][j])
                else:
                    pr = mod_mul(pr, mod_sub(1, p[i][j]))
            pr_e[e] = pr
        pr_table.append(pr_e)

    # cur: dict mapping bitset (as integer) to mint
    cur = {1: 1}  # bitset with only bit 0 set
    for i in range(N):
        nxt = {}
        for b, prob in cur.items():
            # get list of masks set in b
            ones = []
            bb = b
            while bb:
                lsb = bb & -bb
                x = (lsb.bit_length() - 1)
                ones.append(x)
                bb ^= lsb
            # iterate over all e
            for e in range(1<<N):
                pr = pr_table[i][e]
                if pr == 0:
                    continue
                nb = 0
                for x in ones:
                    # for each r in e not in x
                    r = 0
                    ee = e
                    while ee:
                        lsb = ee & -ee
                        r = (lsb.bit_length() - 1)
                        if not ((x >> r) & 1):
                            nb |= (1 << (x | (1 << r)))
                        ee ^= lsb
                if nb:
                    nxt[nb] = mod_add(nxt.get(nb, 0), mod_mul(prob, pr))
        cur = nxt

    ans = 0
    full_mask = (1 << N) - 1
    for b, prob in cur.items():
        if (b >> full_mask) & 1:
            ans = mod_add(ans, prob)
    print(ans)

if __name__ == "__main__":
    main()

