import sys

mo = 1000000007

def mat_mul(a, b, sz):
    # a and b are sz x sz matrices (list of lists)
    # returns a*b mod mo
    c = [[0]*sz for _ in range(sz)]
    for i in range(sz):
        for k in range(sz):
            if a[i][k] == 0:
                continue
            aik = a[i][k]
            for j in range(sz):
                c[i][j] = (c[i][j] + aik * b[k][j]) % mo
    return c

def mat_identity(sz):
    I = [[0]*sz for _ in range(sz)]
    for i in range(sz):
        I[i][i] = 1
    return I

def jia(x, d, sz):
    # rotate rows and columns by d, except last row/col (index sz-1)
    ret = [[0]*sz for _ in range(sz)]
    for i in range(sz):
        for j in range(sz):
            ni = i if i == sz-1 else (i + d) % (sz-1)
            nj = j if j == sz-1 else (j + d) % (sz-1)
            ret[ni][nj] = x[i][j] % mo
    return ret

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    sz = k + 1  # matrix size

    # digits in base k
    nu = []
    temp = n
    while temp > 0:
        nu.append(temp % k)
        temp //= k
    # if n==0, nu is empty

    # a[0] : identity with first row all 1s
    a0 = [[0]*sz for _ in range(sz)]
    for i in range(sz):
        a0[i][i] = 1
    for j in range(sz):
        a0[0][j] = 1
    a = [a0]  # list of matrices

    # compute a[i] for i=1..len(nu)-1
    for i in range(1, len(nu)):
        now = mat_identity(sz)
        for j in range(k):
            now = mat_mul(now, jia(a[i-1], j, sz), sz)
        a.append(now)

    # combine digits
    ans = mat_identity(sz)
    ad = 0
    for i in range(len(nu)-1, -1, -1):
        for j in range(nu[i]):
            ans = mat_mul(ans, jia(a[i], (j + ad) % k, sz), sz)
        ad = (ad + nu[i]) % k

    # compute result
    ret = 0
    for i in range(sz):
        ret = (ret + ans[i][k]) % mo
    print(ret)

if __name__ == "__main__":
    main()

