import sys

MOD = 1000000007

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            aik = A[i][k]
            if aik:
                for j in range(n):
                    C[i][j] = (C[i][j] + aik * B[k][j]) % mod
    return C

def mat_identity(n):
    I = [[0] * n for _ in range(n)]
    for i in range(n):
        I[i][i] = 1
    return I

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    size = m + 1

    # bi is a 2D list of matrices, we will allocate as needed
    # maximum x is such that m^x <= n, but we allocate up to 65 for safety
    bi = [[None] * 65 for _ in range(65)]

    # Initialize bi[0][0]
    mat0 = [[0] * size for _ in range(size)]
    for i in range(size):
        mat0[i][i] = 1
        mat0[0][i] = 1
    bi[0][0] = mat0

    # Compute x and y
    y = 1
    x = 0
    while y * m <= n:
        y *= m
        x += 1

    # Build matrices for t = 0..x
    for t in range(0, x + 1):
        if t > 0:
            # bi[t][0] = bi[t-1][0] * product_{i=1}^{m-1} bi[t-1][i]
            prod = [row[:] for row in bi[t-1][0]]
            for i in range(1, m):
                prod = mat_mul(prod, bi[t-1][i], MOD)
            bi[t][0] = prod

        # For i = 1..m-1
        for i in range(1, m):
            # copy bi[t][i-1]
            mat = [row[:] for row in bi[t][i-1]]
            # swap rows j and j+1 for j from m-2 down to 0
            for j in range(m-2, -1, -1):
                for k in range(size):
                    mat[j][k], mat[j+1][k] = mat[j+1][k], mat[j][k]
            # swap columns j and j+1 for j from m-2 down to 0
            for j in range(m-2, -1, -1):
                for k in range(size):
                    mat[k][j], mat[k][j+1] = mat[k][j+1], mat[k][j]
            bi[t][i] = mat

    # Identity matrix I
    I = mat_identity(size)

    add = 0
    z = 0
    # Use the computed x and y from earlier
    while add < n:
        if add <= n - y:
            add += y
            I = mat_mul(I, bi[x][z], MOD)
            z = (z + 1) % m
        else:
            y //= m
            x -= 1

    ans = 0
    for i in range(size):
        ans = (ans + I[i][m]) % MOD
    print(ans)

if __name__ == "__main__":
    main()

