        self.f = [[0] * (d + 1) for _ in range(d + 1)]

    def __mul__(self, other):
        d = self.d
        res = Matrix(d)
        for i in range(d + 1):
            for k in range(d + 1):
                aik = self.f[i][k]
                if aik == 0:
                    continue
                for j in range(d + 1):
                    res.f[i][j] = (res.f[i][j] + aik * other.f[k][j]) % MOD
        return res

def rotate(u, d):
    u = (u + d) % d
    res = Matrix(d)
    for i in range(d):
        res.f[i][(i + u) % d] = 1
    res.f[d][d] = 1
    return res

def init(bas, d):
    bas[0] = Matrix(d)
    for i in range(1, d):
        bas[0].f[i][i] = 1
    bas[0].f[d][0] = 1
    bas[0].f[d][d] = 2
    bas[0].f[0][d] = -1

