        for _ in range(d):
            bas[i] = bas[i] * bas[i - 1] * rotate(1, d)

    ans = rotate(0, d)
    for i in range(cur - 1, -1, -1):
        for _ in range(a[i]):
            ans = ans * bas[i] * rotate(1, d)

    print((ans.f[d][d] + MOD) % MOD)

if __name__ == "__main__":
    main()

