import sys

MOD = 1000000007

def zero_mat(m):
    return [[0] * (m + 1) for _ in range(m + 1)]

def mul(A, B, m):
    C = zero_mat(m)
    for i in range(m + 1):
        for k in range(m + 1):
            aik = A[i][k]
            if aik == 0:
                continue
            for j in range(m + 1):
                C[i][j] = (C[i][j] + aik * B[k][j]) % MOD
    return C

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])

    # compute digits of n in base m (least significant first)
    v = [0] * 65
    v[0] = n
    length = 0
    while v[length] != 0:
        v[length + 1] = v[length] // m
        v[length] %= m
        length += 1

    # if n == 0, length is 0, no digits
    T = []
    s1 = []
    s2 = []

    for i in range(length):
        T_i = [None] * m
        if i == 0:
            for j in range(m):
                mat = zero_mat(m)
                mat[m][m] = 1
                for a in range(m):
                    if a != j:
                        mat[a][a] = 1
                    else:
                        for b in range(m + 1):
                            mat[a][b] = 1
                T_i[j] = mat
        else:
            for j in range(m):
                if j == 0:
                    T_i[j] = s2[i - 1][0]  # reference copy, but never modified later
                else:
                    T_i[j] = mul(s2[i - 1][j], s1[i - 1][j - 1], m)
        T.append(T_i)

        # compute s1[i]
        s1_i = [None] * m
        s1_i[0] = T_i[0]
        for j in range(1, m):
            s1_i[j] = mul(s1_i[j - 1], T_i[j], m)
        s1.append(s1_i)

        # compute s2[i]
        s2_i = [None] * m
        s2_i[m - 1] = T_i[m - 1]
        for j in range(m - 2, -1, -1):
            s2_i[j] = mul(T_i[j], s2_i[j + 1], m)
        s2.append(s2_i)

    # initial matrix S: first row all 1, rest 0
    S = zero_mat(m)
    for i in range(m + 1):
        S[0][i] = 1

    j = 0
    for i in range(length - 1, -1, -1):
        for _ in range(v[i]):
            S = mul(S, T[i][j], m)
            j = (j + 1) % m

    print(S[0][m])

