import sys

MOD = 10**9 + 7

def sum_mod(a, b):
    s = a + b
    if s >= MOD:
        s -= MOD
    return s

def sub_mod(a, b):
    s = a - b
    if s < 0:
        s += MOD
    return s

def mult_mod(a, b):
    return (a * b) % MOD

def matrix_mult(a, b, k):
    c = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        for j in range(k + 1):
            for t in range(k + 1):
                c[i][t] = sum_mod(c[i][t], mult_mod(a[i][j], b[j][t]))
    return c

def shift_by_1(mat, k):
    c = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        for j in range(k + 1):
            ni = i
            if ni < k:
                ni = (ni + k - 1) % k
            nj = j
            if nj < k:
                nj = (nj + k - 1) % k
            c[i][j] = mat[ni][nj]
    return c

def init(n, k):
    digs = 0
    cop = n
    while cop > 0:
        cop //= k
        digs += 1
    pref = [None] * (digs + 1)
    pref[0] = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(1, k):
        pref[0][i][i] = 1
    pref[0][0][k] = 1
    pref[0][k][0] = MOD - 1
    pref[0][k][k] = 2
    for step in range(digs):
        pref[step + 1] = [row[:] for row in pref[step]]
        cur = [row[:] for row in pref[step]]
        for i in range(1, k):
            cur = shift_by_1(cur, k)
            pref[step + 1] = matrix_mult(pref[step + 1], cur, k)
    return pref

def solve(n, k, pref):
    if n == 0:
        c = [[0] * (k + 1) for _ in range(k + 1)]
        for i in range(k + 1):
            c[i][i] = 1
        return c
    dig = 0
    pw = 1
    while pw <= n // k:
        pw *= k
        dig += 1
    if n == pw:
        return [row[:] for row in pref[dig]]
    steps = n // pw
    left = n - steps * pw
    cur_mat = solve(0, k, pref)
    cur_coef = [row[:] for row in pref[dig]]
    for _ in range(steps):
        cur_mat = matrix_mult(cur_mat, cur_coef, k)
        cur_coef = shift_by_1(cur_coef, k)
    other_mat = solve(left, k, pref)
    for _ in range(steps):
        other_mat = shift_by_1(other_mat, k)
    return matrix_mult(cur_mat, other_mat, k)

def main():
