import sys

MOD = 1000000007
LIM = (1 << 63) - 1 - MOD * MOD  # approximate LLONG_MAX - MOD*MOD

def mmult(A, B, C):
    """C = A * B (mod MOD), C is modified in place."""
    n = len(A)  # base+1
    for i in range(n):
        for j in range(n):
            cur = 0
            for k in range(n):
                if cur > LIM:
                    cur %= MOD
                cur += A[i][k] * B[k][j]
            C[i][j] = cur % MOD

def mcopy(A, B):
    """Copy matrix A into B."""
    n = len(A)
    for i in range(n):
        for j in range(n):
            B[i][j] = A[i][j]

def run():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    base = int(data[1])

    # mat[i][j] is a (base+1)x(base+1) matrix
    # We'll allocate as list of lists of matrices
    # First compute ci and step
    ci = 0
    step = 1
    while step <= n // base:
        ci += 1
        step *= base

    # Initialize mat[0][i] for i in range(base)
    # We'll create a list of lists: mat[i] is a list of base matrices
    mat = [[None for _ in range(base)] for _ in range(ci + 1)]
    for i in range(base):
        # create identity-like matrix: 1 if i==j or j==k else 0
        M = [[0] * (base + 1) for _ in range(base + 1)]
        for j in range(base + 1):
            for k in range(base + 1):
                if i == j or j == k:
                    M[j][k] = 1
        mat[0][i] = M

    # Build higher powers
    for i in range(1, ci + 1):
        for j in range(base):
            # start with identity matrix
            M = [[0] * (base + 1) for _ in range(base + 1)]
            for r in range(base + 1):
                M[r][r] = 1
            tmp = [[0] * (base + 1) for _ in range(base + 1)]
            for k in range(base):
                mmult(M, mat[i-1][(j + k) % base], tmp)
                mcopy(tmp, M)
            mat[i][j] = M

    # Initialize 'have' as identity
    have = [[0] * (base + 1) for _ in range(base + 1)]
    for r in range(base + 1):
        have[r][r] = 1
    tmp = [[0] * (base + 1) for _ in range(base + 1)]

    cj = 0
    # Process from highest power down to 0
    for i in range(ci, -1, -1):
