    sump[0][0] = f[0][0];
    sums[0][k - 1] = f[0][k - 1];

    for (int i = 1; i < k; i++) {
      sump[0][i] = f[0][i] * sump[0][i - 1];
    }

    for (int i = k - 2; i >= 0; i--) {
      sums[0][i] = sums[0][i + 1] * f[0][i];
    }

    for (int i = 1; i < cnt; i++) {
      for (int j = 0; j < k; j++) {
        f[i][j] = j == 0 ? sums[i - 1][j] : sump[i - 1][j - 1] * sums[i - 1][j];
