import sys

MOD = 1000000007

def mat_mul(A, B, n):
    # A and B are (n+1)x(n+1) matrices (1-indexed), returns new matrix
    C = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        for k in range(1, n + 2):
            if A[i][k] == 0:
                continue
            aik = A[i][k]
            for j in range(1, n + 2):
                C[i][j] = (C[i][j] + aik * B[k][j]) % MOD
    return C

def identity(n):
    E = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        E[i][i] = 1
    return E

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    m = int(data[0])
    n = int(data[1])

    E = identity(n)
