import sys

MOD = 1000000007

def mat_mul(A, B, m):
    """Multiply two (m+1)x(m+1) matrices modulo MOD."""
    size = m + 1
    C = [[0] * size for _ in range(size)]
    for i in range(size):
        for k in range(size):
            aik = A[i][k]
            if aik:
                for j in range(size):
                    C[i][j] = (C[i][j] + aik * B[k][j]) % MOD
    return C

def mat_identity(m):
    size = m + 1
    I = [[0] * size for _ in range(size)]
    for i in range(size):
        I[i][i] = 1
    return I

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])

    # Compute base-m digits of n (least significant first)
    digits = []
    n2 = n
    while n2:
        digits.append(n2 % m)
        n2 //= m
    if not digits:
        digits = [0]
    L = len(digits)  # number of digits

    # Initialize ans as a matrix with first row all 1, rest 0
    size = m + 1
    ans = [[0] * size for _ in range(size)]
    for j in range(size):
        ans[0][j] = 1

    # Prepare storage for A, P, S matrices
    A = [[None] * m for _ in range(L)]
    P = [[None] * m for _ in range(L)]
    S = [[None] * m for _ in range(L)]

    for i in range(L):
        if i == 0:
            # i = 0: special construction
            for j in range(m):
                mat = [[0] * size for _ in range(size)]
                # Set last row (index m) to identity (only diagonal)
                mat[m][m] = 1
                for k in range(m):
                    if k != j:
                        mat[k][k] = 1
                    else:
                        # row j: all ones
                        for l in range(size):
                            mat[k][l] = 1
                A[i][j] = mat
        else:
            # i > 0: use S[i-1] and P[i-1]
            A[i][0] = S[i-1][0]
            for j in range(1, m):
                A[i][j] = mat_mul(S[i-1][j], P[i-1][j-1], m)

        # Compute prefix products P[i][j]
        P[i][0] = A[i][0]
        for j in range(1, m):
            P[i][j] = mat_mul(P[i][j-1], A[i][j], m)

        # Compute suffix products S[i][j]
        S[i][m-1] = A[i][m-1]
        for j in range(m-2, -1, -1):
            S[i][j] = mat_mul(A[i][j], S[i][j+1], m)

    # Main loop over digits from most significant to least
    j = 0
    for i in range(L-1, -1, -1):
        d = digits[i]
        for _ in range(d):
            ans = mat_mul(ans, A[i][j], m)
            j = (j + 1) % m

    # Output the required element
    print(ans[0][m] % MOD)

if __name__ == "__main__":
    main()

