import sys
sys.setrecursionlimit(1000000)

def fpow(a, b, p):
    return pow(a, b, p)

def lowbit(x):
    return x & -x

def init(n, p):
    fac = [1] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = fac[i-1] * i % p
    inv = [1] * (n + 1)
    inv[n] = fpow(fac[n], p-2, p)
    for i in range(n, 0, -1):
        inv[i-1] = inv[i] * i % p
    return fac, inv

def solve(cur, S, n, k, p, fac, inv, memo):
    key = (cur, S)
    if key in memo:
        return memo[key]
    if S == 0:
        res = fac[n]
        for i in range(1, cur + 1):
            res = res * (k - i + 1) % p
        memo[key] = res
        return res
    res = 0
    U = S - lowbit(S)
    T = U
    while T:
        res = (res + inv[S - T] * solve(cur + 1, T, n, k, p, fac, inv, memo)) % p
        T = (T - 1) & U
    res = (res + inv[S] * solve(cur + 1, 0, n, k, p, fac, inv, memo)) % p
    memo[key] = res
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k, p = map(int, data[:3])
    ans = pow(k, n, p)
    if n % 2 == 0:
        fac, inv = init(n, p)
        memo = {}
        ans = (ans - solve(0, n, n, k, p, fac, inv, memo) + p) % p
    print(ans)

if __name__ == "__main__":
    main()

