import sys

def pwr(x, y, Mo):
    z = 1
    while y:
        if y & 1:
            z = (z * x) % Mo
        x = (x * x) % Mo
        y >>= 1
    return z

def FWT(a, length, Mo):
    i = 1
    while i < length:
        j = 0
        while j < length:
            for k in range(i):
                a[j + k + i] = (a[j + k + i] + a[j + k]) % Mo
            j += i * 2
        i <<= 1

def IFWT(a, length, Mo):
    i = 1
    while i < length:
        j = 0
        while j < length:
            for k in range(i):
                a[j + k + i] = (a[j + k + i] - a[j + k]) % Mo
            j += i * 2
        i <<= 1

def get_ln(h, p, n, inv, Mo):
    p[0] = 0
    for i in range(1, n + 1):
        p[i] = h[i] * i % Mo
        for j in range(1, i):
            p[i] = (p[i] - p[j] * h[i - j] % Mo * j) % Mo
        p[i] = p[i] * inv[i] % Mo
    for i in range(0, n + 1):
        h[i] = (p[i] + Mo) % Mo

def get_exp(h, p, n, inv, Mo):
    p[0] = 1
    for i in range(1, n + 1):
        p[i] = 0
        for j in range(1, i + 1):
            p[i] = (p[i] + h[j] * p[i - j] % Mo * j) % Mo
        p[i] = p[i] * inv[i] % Mo
    for i in range(0, n + 1):
        h[i] = p[i] % Mo

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    L = int(data[0])
    k = int(data[1])
    Mo = int(data[2])

    all_val = pwr(k, L, Mo)
    if L & 1:
        print(all_val)
        return

    # find bits of L
    bits = []
    for i in range(19):
        if (L >> i) & 1:
            bits.append(1 << i)
    n = len(bits)
    length = 1 << n

    # factorials and inverses up to L
    fac = [1] * (L + 1)
    for i in range(1, L + 1):
        fac[i] = fac[i - 1] * i % Mo
    inv = [0] * (L + 1)
    inv[L] = pwr(fac[L], Mo - 2, Mo)
    for i in range(L - 1, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % Mo

    # popcount for numbers up to L
    cnt = [0] * (L + 1)
    for s in range(1, L + 1):
        cnt[s] = cnt[s ^ (s & -s)] + 1

    # initialize g
    g = [[0] * length for _ in range(n + 1)]
    for i in range(length):
        s = 0
        for j in range(n):
            if (i >> j) & 1:
                s += bits[j]
        g[cnt[i]][i] = inv[s] % Mo

    # recompute inverses for numbers 2..n (used in ln/exp)
    for i in range(2, n + 1):
        inv[i] = (Mo - Mo // i) * inv[Mo % i] % Mo

    # FWT each row of g
    for i in range(n + 1):
        FWT(g[i], length, Mo)

    h = [0] * (n + 1)
    p = [0] * (n + 1)
    f = [[0] * length for _ in range(n + 1)]
    for s in range(length):
