import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    mod = int(data[2])

    # if n is odd, answer is k^n mod mod
    if n & 1:
        print(pow(k, n, mod))
        return

    # number of bits set in n (only bits 0..17 matter, n < 2^18)
    m = bin(n).count('1')

    # precompute modular inverses of 1..n
    inv = [0] * (n + 1)
    inv[0] = 1
    inv[1] = 1
    for i in range(2, n + 1):
        # inv[i] = - (mod // i) * inv[mod % i] % mod
        inv[i] = (mod - (mod // i) * inv[mod % i] % mod) % mod

    # popcount array
    siz = [0] * (n + 1)
    for i in range(1, n + 1):
        siz[i] = siz[i >> 1] + (i & 1)

    # f: dictionary mapping submask -> list of length 19 (coefficients)
    f = {}
    s = 1
    for i in range(n + 1):
        s = s * inv[i] % mod
        if (i & n) == i:
            f[i] = [0] * 19
            f[i][siz[i]] = s

    # forward SOS DP (subset sum)
    for i in range(18):
        if (n >> i) & 1:
            s = n
            while s:
                if (s >> i) & 1:
                    for a in range(m + 1):
                        f[s][a] = (f[s][a] + f[s ^ (1 << i)][a]) % mod
                s = (s - 1) & n

    # polynomial exponentiation for each submask
    for i in list(f.keys()):
        t = f[i][:]                     # copy original polynomial
        # set f[i] to identity polynomial [1,0,0,...]
        f[i] = [1 if a == 0 else 0 for a in range(m + 1)]
        y = k
        while y:
            if y & 1:
                # multiply f[i] by t
                p = f[i][:]
                f[i] = [0] * (m + 1)
                for a in range(m + 1):
                    if t[a]:
                        for b in range(m + 1 - a):
                            f[i][a + b] = (f[i][a + b] + t[a] * p[b]) % mod
            y >>= 1
            if y:
                # square t
                t2 = [0] * (m + 1)
                for a in range(m + 1):
                    if t[a]:
                        for b in range(m + 1 - a):
                            t2[a + b] = (t2[a + b] + t[a] * t[b]) % mod
                t = t2

    # inverse SOS DP (subtract)
    for i in range(18):
        if (n >> i) & 1:
            s = n
            while s:
                if (s >> i) & 1:
                    for a in range(m + 1):
                        f[s][a] = (f[s][a] - f[s ^ (1 << i)][a]) % mod
                s = (s - 1) & n

    # final result
    s = f[n][m]
    for i in range(n, 0, -1):
        s = s * i % mod
    ans = (pow(k, n, mod) - s) % mod
    print(ans)

