import sys

def init(n, P):
    fac = [1] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = fac[i - 1] * i % P
    ifac = [1] * (n + 1)
    ifac[n] = pow(fac[n], P - 2, P)
    for i in range(n, 0, -1):
        ifac[i - 1] = ifac[i] * i % P
    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = (P - P // i) * inv[P % i] % P
    return fac, ifac, inv

def FMT(f, n, P):
    l = 1
    while l < n:
        for i in range(0, n, l << 1):
            for j in range(l):
                f[i + j + l] = (f[i + j + l] + f[i + j]) % P
        l <<= 1

def IFMT(f, n, P):
    l = 1
    while l < n:
        for i in range(0, n, l << 1):
            for j in range(l):
                f[i + j + l] = (f[i + j + l] - f[i + j]) % P
        l <<= 1

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    n = next(it)
    k = next(it)
    P = next(it)

    ans = pow(k, n, P)

    if n % 2 == 0:
        m = n.bit_length()  # floor(log2(n)) + 1
        size = 1 << m
        fac, ifac, inv = init(size, P)

        # f[popcount][mask]
        f = [[0] * size for _ in range(m + 1)]
        for i in range(size):
            pop = i.bit_count()
            f[pop][i] = ifac[i]

        for j in range(m + 1):
            FMT(f[j], size, P)

        for i in range(size):
            # copy column i into F
            F = [f[j][i] for j in range(m + 1)]
            G = [0] * (m + 1)

            # ln(F) -> G
            G[0] = 0
            for ii in range(1, m + 1):
                s = 0
                for j in range(1, ii):
                    s = (s + F[ii - j] * G[j] * j) % P
                G[ii] = (F[ii] + s * (P - inv[ii])) % P

            # multiply G by k
            for j in range(m + 1):
                G[j] = (G[j] * k) % P

            # exp(G) -> F2
            F2 = [0] * (m + 1)
            F2[0] = 1
            for ii in range(1, m + 1):
                s = 0
                for j in range(1, ii + 1):
                    s = (s + F2[ii - j] * G[j] * j) % P
                F2[ii] = (s * inv[ii]) % P

            # copy back
            for j in range(m + 1):
                f[j][i] = F2[j]

        pop_n = n.bit_count()
        IFMT(f[pop_n], size, P)
        ans = (P + ans - f[pop_n][n] * fac[n] % P) % P

