import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k, M = map(int, data[:3])
    if n & 1:
        print(pow(k, n, M))
        return
    original_n = n
    n >>= 1

    # factorials and inverse factorials up to original_n
    fac = [1] * (original_n + 1)
    for i in range(1, original_n + 1):
        fac[i] = fac[i-1] * i % M
    inv = [0] * (original_n + 1)
    inv[original_n] = pow(fac[original_n], M-2, M)
    for i in range(original_n - 1, -1, -1):
        inv[i] = inv[i+1] * (i+1) % M

    SIZE = 1 << 17
    # a[popcount][mask] = inv[2*mask] for mask <= n, else 0
    a = [[0] * SIZE for _ in range(18)]
    for i in range(n + 1):
        if i < SIZE:
            pp = i.bit_count()
            a[pp][i] = inv[i * 2] % M

    # SOS DP on a (subset sum over bits)
    for i in range(17):
        for j in range(17):
            step = 1 << j
            for u in range(SIZE):
                if u & step:
