        b[mask] = dp[k][pn] % M

    # SOS transform on b (inverse subset sum)
    for i in range(17):
        step = 1 << i
        for j in range(SIZE):
            if j & step:
                b[j] = (b[j] - b[j ^ step]) % M

    ans = (pow(k, original_n, M) - (b[n] % M) * fac[original_n]) % M
    print(ans % M)

