import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    K = int(data[1])
    mod = int(data[2])

    ANS = pow(K, n, mod)
    if n & 1:
        print(ANS)
        return

    Lg = 18
    N = bin(n).count('1')
    Nbef = n

    vec = [i for i in range(Lg) if (n >> i) & 1]
    n = (1 << N) - 1

    # factorial and inverse factorial up to Nbef
    fac = [1] * (Nbef + 1)
    for i in range(1, Nbef + 1):
        fac[i] = fac[i-1] * i % mod
    ifac = [1] * (Nbef + 1)
    ifac[Nbef] = pow(fac[Nbef], mod - 2, mod)
    for i in range(Nbef - 1, -1, -1):
        ifac[i] = ifac[i+1] * (i+1) % mod

    # Ans[mask][k] = polynomial coefficient
    Ans = [[0] * (N + 1) for _ in range(n + 1)]

    for mask in range(n + 1):
        Real = 0
        for j in range(N):
            if (mask >> j) & 1:
                Real += 1 << vec[j]
        k = bin(mask).count('1')
        Ans[mask][k] = ifac[Real] % mod

    # subset transform (SOS DP)
    def trans1(a):
        for i in range(N):
            for msk in range(n, -1, -1):
                if (msk >> i) & 1:
                    prev = msk ^ (1 << i)
                    for j in range(N + 1):
                        a[msk][j] = (a[msk][j] + a[prev][j]) % mod

    def trans2(a):
        for i in range(N):
            for msk in range(n, -1, -1):
                if (msk >> i) & 1:
                    prev = msk ^ (1 << i)
                    for j in range(N + 1):
                        a[msk][j] = (a[msk][j] - a[prev][j]) % mod

    trans1(Ans)

    # polynomial multiplication (convolution) of degree N
    def mul(ans, a, b):
        tmp = [0] * (N + 1)
        for i in range(N + 1):
            s = 0
            for j in range(i + 1):
                s = (s + a[j] * b[i - j]) % mod
            tmp[i] = s
        ans[:] = tmp

    # exponentiate each polynomial to power K
    for i in range(n + 1):
        KK = K
        tmp2 = [0] * (N + 1)
        tmp2[0] = 1
        while KK:
            if KK & 1:
                mul(tmp2, tmp2, Ans[i])
            mul(Ans[i], Ans[i], Ans[i])
            KK >>= 1
        Ans[i] = tmp2[:]

    trans2(Ans)

    ANS = (ANS - Ans[n][N] * fac[Nbef]) % mod
    if ANS < 0:
        ANS += mod
    print(ANS)

if __name__ == "__main__":
    solve()

