import sys

def qpow(a, n, P):
    r = 1 % P
    a %= P
    while n:
        if n & 1:
            r = (r * a) % P
        a = (a * a) % P
        n >>= 1
    return r

def inv(x, P):
    if x <= 1:
        return 1
    return inv(P % x, P) * (P - P // x) % P

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k, P = map(int, data[:3])

    # Precompute factorials up to n
    fac = [1] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = (fac[i-1] * i) % P

    ifac = [1] * (n + 1)
    if n >= 0:
        ifac[n] = inv(fac[n], P)
        for i in range(n, 0, -1):
            ifac[i-1] = (ifac[i] * i) % P

    ans = qpow(k, n, P)

    if n % 2 == 0:
        f = [0] * (n + 1)
        g = [0] * (n + 1)
        f[n] = fac[n]

        for z in range(1, k + 1):
            # Reset g to zeros
            g = [0] * (n + 1)

            i = n
            while i:
                if f[i]:
                    j = i
                    while j and 2 * j >= i:
                        g[i ^ j] = (g[i ^ j] + f[i] * ifac[j]) % P
                        j = (j - 1) & i
                i = (i - 1) & n

            f, g = g, f  # swap

            res = f[0]
            for j in range(z):
                res = (res * (k - j)) % P
            ans = (ans - res) % P

    print(ans % P)

if __name__ == "__main__":
    main()

