import sys
from array import array

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k, M = data[0], data[1], data[2]

    # modular arithmetic helpers
    def add(x: int, y: int) -> int:
        return (x + y) % M
    def sub(x: int, y: int) -> int:
        return (x - y) % M
    def mul(x: int, y: int) -> int:
        return (x * y) % M
    def power(x: int, y: int) -> int:
        return pow(x, y, M)
    def inv(x: int) -> int:
        return pow(x, M - 2, M)

    # factorials
    fac = [1] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = mul(fac[i - 1], i)
    ifac = [1] * (n + 1)
    ifac[n] = inv(fac[n])
    for i in range(n - 1, -1, -1):
        ifac[i] = mul(ifac[i + 1], i + 1)

    # DP memoization: flat array of size (n+1)*(k+1)
    size = (n + 1) * (k + 1)
    f = array('i', [-1]) * size

    def get_f(s: int, c: int) -> int:
        return f[s * (k + 1) + c]

    def set_f(s: int, c: int, val: int) -> None:
        f[s * (k + 1) + c] = val

    sys.setrecursionlimit(1000000)

    def dp(s: int, c: int) -> int:
        if s == 0:
            return 1
        if c == k:
            return 0
        res = get_f(s, c)
        if res != -1:
            return res
        res = 0
        hb = 1 << (s.bit_length() - 1)   # highest bit of s
        sub = s
        while sub:
            if not (sub & hb):
                break
            # process sub
            term = mul(ifac[sub], k - c, dp(s ^ sub, c + 1))
            res = add(res, term)
            sub = (sub - 1) & s
        set_f(s, c, res)
        return res

    if n & 1:
        ans = power(k, n)
    else:
        ans = sub(power(k, n), mul(fac[n], dp(n, 0)))
    sys.stdout.write(str(ans) + '\n')

if __name__ == "__main__":
    solve()

