def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a // gcd(a, b) * b

def fpow(n, k, p):
    r = 1
    while k:
        if k & 1:
            r = r * n % p
        n = n * n % p
        k >>= 1
    return r

def chkmin(a, val):
    if val < a[0]:
        a[0] = val
        return 1
    return 0

def chkmax(a, val):
    if a[0] < val:
        a[0] = val
        return 1
    return 0

def isqrt(k):
    r = int(math.isqrt(k)) + 1
    while r * r > k:
        r -= 1
    return r

def icbrt(k):
    r = int(round(k ** (1/3))) + 1
    while r * r * r > k:
        r -= 1
    return r

