import sys
from collections import deque

# Global variables
mod = 0
jc = []
inv = []
Log = []
jc2 = []
dp_dict = {}

def getcnt(x):
    cnt = 0
    while x and x % 2 == 0:
        cnt += 1
        x //= 2
    return cnt

def ksm(x, y):
    ret = 1
    while y:
        if y & 1:
            ret = (ret * x) % mod
        x = (x * x) % mod
        y >>= 1
    return ret

def C(n, m):
    if m < 0 or m > n:
        return 0
    return jc[n] * inv[m] % mod * inv[n - m] % mod

def dfs(n, k):
    if n == 0:
        return 1
    if k == 0:
        return 0
    key = (n, k)
    if key in dp_dict:
        return dp_dict[key]
    di = 1 << Log[n]
    ret = 0
    for i in range(n, di - 1, -2):
        ret = (ret + C(n, i) * dfs(n - i, k - 1) % mod * k) % mod
    dp_dict[key] = ret
    return ret

def bfs(n, k):
    global dp_dict, mod
    que = deque()
    que.append((n, k))
    tp = []
    vis = set()
    vis.add((n, k))
    while que:
        n_cur, k_cur = que.popleft()
        tp.append((n_cur, k_cur))
        if n_cur == 0 or k_cur == 0:
            continue
        di = 1 << Log[n_cur]
        for i in range(n_cur, di - 1, -2):
            if jc2[i] + jc2[n_cur - i] == jc2[n_cur]:
                nxt = (n_cur - i, k_cur - 1)
                if nxt not in vis:
                    vis.add(nxt)
                    que.append(nxt)
    dp_local = {}
    for n_cur, k_cur in reversed(tp):
        if n_cur == 0:
            dp_local[(n_cur, k_cur)] = 1
            continue
        if k_cur == 0:
            dp_local[(n_cur, k_cur)] = 0
            continue
        di = 1 << Log[n_cur]
        ret = 0
        for i in range(n_cur, di - 1, -2):
            if jc2[i] + jc2[n_cur - i] == jc2[n_cur]:
                ret = (ret + C(n_cur, i) * dp_local[(n_cur - i, k_cur - 1)] % mod * k_cur) % mod
        dp_local[(n_cur, k_cur)] = ret
    dp_dict.update(dp_local)
    return dp_local[(n, k)]

def main():
    global mod, jc, inv, Log, jc2, dp_dict
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    mod = int(data[2])
    MAXN = 262150
    # Precompute factorials and inverses up to MAXN
    jc = [1] * (MAXN + 1)
    for i in range(1, MAXN + 1):
        jc[i] = jc[i - 1] * i % mod
    inv = [1] * (MAXN + 1)
    inv[MAXN] = ksm(jc[MAXN], mod - 2)
    for i in range(MAXN, 0, -1):
        inv[i - 1] = inv[i] * i % mod
    # Precompute Log and jc2
