    Log[0] = -1
    jc2 = [0] * (MAXN + 1)
    for i in range(1, MAXN + 1):
        Log[i] = Log[i >> 1] + 1
        jc2[i] = jc2[i - 1] + getcnt(i)
    dp_dict = {}
