MOD = None  # will be set from input
maxn = 500 + 5

def upd(x):
    if x < 0:
        return x + MOD
    if x >= MOD:
        return x - MOD
    return x

def add(x, y):
    return upd(x + y)

def ksm(x, k):
    ans = 1
    while k:
        if k & 1:
            ans = ans * x % MOD
        x = x * x % MOD
        k >>= 1
    return ans

jc = [0] * (maxn * 4)
inv = [0] * (maxn * 4)

def init(n):
    jc[0] = 1
    for i in range(1, n + 1):
        jc[i] = jc[i - 1] * i % MOD
    inv[n] = ksm(jc[n], MOD - 2)
    for i in range(n - 1, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

def C(n, m):
    if n < 0 or m < 0 or n < m:
        return 0
    return jc[n] * inv[n - m] % MOD * inv[m] % MOD

def S(n):
    return n * (n + 1) // 2

def multiply(A, B):
    C = [0] * (len(A) + len(B) - 1)
    for i in range(len(A)):
        for j in range(len(B)):
            C[i + j] = add(C[i + j], A[i] * B[j] % MOD)
    return C

def G(n, m):
    return C(m + n - 1, n - 1)

