def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, P = map(int, data[:3])
    maxn = n + 1
    # binomial coefficients C[i][j] modulo P
    C = [[0] * maxn for _ in range(maxn)]
    for i in range(maxn):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P

    f1 = [0] * maxn
    g1 = [0] * maxn
    f1[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            f1[i] = (f1[i] + f1[j - 1] * f1[i - j] % P * C[i - 1][j - 1]) % P
            t = (f1[j - 1] * g1[i - j] + g1[j - 1] * f1[i - j]) % P
            t = t * (i + 1) % P
            g1[i] = (g1[i] + (f1[j - 1] * f1[i - j] % P * (C[j][2] + C[i - j + 1][2]) % P + t) % P * C[i - 1][j - 1]) % P
        f1[i] = (i + 1) * f1[i] % P

