def mod_pow(a, b, mod):
    res = 1
    while b:
        if b & 1:
            res = res * a % mod
        a = a * a % mod
        b >>= 1
    return res

def mod_inv(a, mod):
    return mod_pow(a, mod - 2, mod)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    mod = int(data[2])

    vmax = 10010
    fact = [1] * (vmax)
    inv_fact = [1] * (vmax)
    for i in range(1, vmax):
        fact[i] = fact[i-1] * i % mod
    inv_fact[vmax-1] = mod_inv(fact[vmax-1], mod)
    for i in range(vmax-2, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % mod

    def choose(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[n-k] % mod * inv_fact[k] % mod

    def binom(a, b):
        return fact[a+b] * inv_fact[a] % mod * inv_fact[b] % mod

    ans = 0
    for length in range(1, m):
