            me = d * (d + 1) // 2
            me = (me * c[i-1][d]) % M
            me = (me * p[d+1][d-1]) % M
            me = (me * g(n + 1 - (d + 1) - 1, i - (d + 1))) % M
            me = (me * p[2][d]) % M
            me = (me * p[n+1][m-i]) % M
            me = (me * p[2][m-i]) % M
            you = (you + me + me) % M

    result = you * (n + 1 - m) % M
    print(result)

