    return a

class T:
    __slots__ = ('cnt', 'sum')
    def __init__(self, cnt=0, sum=0):
        self.cnt = cnt
        self.sum = sum

    def __mul__(self, other):
        s = mul(self.cnt, other.sum)
        s = add(s, mul(self.sum, other.cnt))
        return T(mul(self.cnt, other.cnt), s)

    def __add__(self, other):
        c = add(self.cnt, other.cnt)
        s = add(self.sum, other.sum)
        return T(c, s)

def solve(n, m, mod_):
    global mod
    mod = mod_
