import sys

def addmod(x, mod):
    return x if x < mod else x - mod

def submod(x, mod):
    return x + mod if x < 0 else x

def fpow(x, y, mod):
    ans = 1
    while y:
        if y & 1:
            ans = (ans * x) % mod
        x = (x * x) % mod
        y //= 2
    return ans

class Pt:
    __slots__ = ('f', 'g')
    def __init__(self, f=0, g=0):
        self.f = f
        self.g = g
    def __add__(self, other):
        return Pt(addmod(self.f + other.f, mod), addmod(self.g + other.g, mod))
    def __mul__(self, other):
        return Pt(
            (self.f * other.f) % mod,
            addmod((self.f * other.g) % mod + (self.g * other.f) % mod, mod)
        )

def F(x):
    return (x * (x + 1) // 2) % mod

def main():
    global mod
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    mod = int(data[2])

