    infr = [0] * (pn + 1)
    inv = [0] * (pn + 1)
    fr[0] = infr[0] = 1
    for i in range(1, pn + 1):
        fr[i] = (i * fr[i-1]) % mod
        infr[i] = fpow(fr[i], mod-2, mod)
        inv[i] = fpow(i, mod-2, mod)

