import sys

def spow(a, b, M):
    r = 1
    while b:
        if b & 1:
            r = r * a % M
        a = a * a % M
        b >>= 1
    return r

def Inv(a, M):
    # Fermat's little theorem, assumes M is prime
    return spow(a, M - 2, M)

def f(c, p, M):
    if p == 0:
        return 1
    return spow(c + 1, p - 1, M) * (c + 1 - p) % M

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    c = int(data[0])
    p = int(data[1])
    M = int(data[2])

    N = c + 2
    newt = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        newt[i][0] = newt[i][i] = 1
        for j in range(1, i):
            newt[i][j] = (newt[i-1][j] + newt[i-1][j-1]) % M

    inv_newt = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        for j in range(N + 1):
            if newt[i][j] != 0:
                inv_newt[i][j] = Inv(newt[i][j], M)
            else:
                inv_newt[i][j] = 0  # not used for zero

