import sys
import math

sys.setrecursionlimit(10000)

def solve(pattern, R, C, chooset):
    N = len(pattern)
    base = 0
    for i in range(R + C):
        base += chooset[i][R - 1] * chooset[N - i - 1][R]
    trg = 2 * base - chooset[N][2 * R]

    req = 0
    excl = 0
    for i, ch in enumerate(pattern):
        if ch == 'A':
            req |= (1 << i)
        elif ch == 'B':
            excl |= (1 << i)

    dp = [[0] * (R + C + 1) for _ in range(R + C + 1)]
    dp[0][0] = 1
    for j in range(R + C + 1):
        for k in range(R + C + 1):
            if j >= R - 1 and k >= R:
                break
            if j < R + C and pattern[j + k] != 'B':
                dp[j + 1][k] += dp[j][k]
            if k < R + C and pattern[j + k] != 'A':
                dp[j][k + 1] += dp[j][k]

    M = N - C
    asums2 = [[] for _ in range(R + C + 1)]

    def recurse(L, N, a, na, req, excl, cur, sums):
        if na > N - L:
            return
        if L == N:
            sums.append(cur)
            return
        mask = 1 << L
        if not (req & mask):
            recurse(L + 1, N, a, na, req, excl, cur, sums)
        if na > 0 and not (excl & mask):
            nxt = cur + chooset[a][R - 1] * chooset[L - a][R]
            recurse(L + 1, N, a + 1, na - 1, req, excl, nxt, sums)

    for al in range(R - 1, R + C + 1):
        recurse(M, N, al, R + C - al, req, excl, 0, asums2[al])
        asums2[al].sort(reverse=True)

    unfair = 10**30
    ans = 0
    for a in range(R - 1, R + C + 1):
        for b in range(R, R + C + 1):
            if a > R - 1 and b > R:
                continue
            if dp[a][b] == 0:
                continue
            L = a + b
            for l in range(M - L + 1):
                r = R + C - a - l
                if r > N - M or r < 0:
                    continue
                sums1 = []
                recurse(L, M, a, l, req, excl, 0, sums1)
                sums1.sort(reverse=True)
                sums2 = asums2[a + l]
                p = q = 0
                p2 = q2 = 0
                while p < len(sums1) and q < len(sums2):
                    while p2 < len(sums1) and sums1[p2] == sums1[p]:
                        p2 += 1
                    while q2 < len(sums2) and sums2[q2] == sums2[q]:
                        q2 += 1
                    total = 2 * (sums1[p] + sums2[q])
                    diff = abs(total - trg)
                    if diff < unfair:
                        unfair = diff
                        ans = 0
                    if diff == unfair:
                        ans += (p2 - p) * (q2 - q) * dp[a][b]
                    if total > trg:
                        q = q2
                    else:
                        p = p2
    return (unfair, ans)

